-- AUTOMATISCH ERZEUGT aus daten/ (npm run seed) – nicht von Hand bearbeiten.
-- Teil von supabase/seed.sql: Thema 24 „Abwanderung aus strukturschwachen Regionen“ – Instrumente, Maßnahmen, Prüfeinheiten, Abdeckung.
-- Nach 0-gemeinsam.sql ausführen. Mehrfach ausführbar, gespielte Runden bleiben erhalten.

begin;

delete from public.massnahmen where thema_id = 24;
delete from public.abdeckung where thema_id = 24;
delete from public.pruef_einheiten where thema_id = 24;

-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (9575, 24, 'Kita- und Tagespflegeplätze ausbauen (Land)', 'Studien aus Deutschland zeigen, dass mehr Krippenplätze die Geburtenrate leicht erhöhen, vor allem bei zweiten und dritten Kindern. Der Effekt ist begrenzt, und es fehlen Fachkräfte.', 'belegt', 'https://ifo.de/publikationen/2013/working-paper/does-expanding-public-child-care-encourage-fertility-county-level', 'land', null, true, 'blind'),
  (9576, 24, 'Bestehendes Kita-Netz finanziell sichern, auch im ländlichen Raum (Land)', 'Sichert vorhandene Betreuung bei sinkenden Kinderzahlen und hält Familien vor Ort. Neue Plätze entstehen nicht, deshalb ist kaum Wirkung auf die Geburten zu erwarten.', 'offen', null, 'land', null, true, 'blind'),
  (9577, 24, 'Landesförderung für Kinderwunschbehandlungen (Land)', 'Nach den Kürzungen der Kassenleistungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Zuschüsse wirken also, aber nur für einen kleinen Teil der Geburten.', 'belegt', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'land', null, true, 'blind'),
  (9578, 24, 'Einmaliges Begrüßungsgeld bei Geburt (Land)', 'Studien aus Korea und Australien finden kleine positive Effekte von Geburtsprämien. Bei 2.000 bis 4.000 Euro ist aber kaum eine Änderung der Familienplanung zu erwarten, und es gibt Mitnahmeeffekte.', 'gemischt', 'https://www.ifo.de/en/cesifo/publications/2024/working-paper/baby-bonus-fertility-and-missing-women', 'land', null, true, 'blind'),
  (9579, 24, 'Landesgeldleistungen und Entlastungen für Familien (Land)', 'Finanzielle Entlastung erleichtert das Leben mit Kindern. Studien finden aber meist nur schwache Effekte von Geldleistungen auf die Geburtenzahl, und die Kosten für den Landeshaushalt sind hoch.', 'gemischt', 'https://www.ifo.de/en/cesifo/publications/2024/working-paper/baby-bonus-fertility-and-missing-women', 'land', null, true, 'blind'),
  (9580, 24, 'Einsatz für bundesrechtliche Familienleistungen wie Familiensplitting oder Kindergrundsicherung (Land)', 'Steuerliche Anreize erhöhen die Geburtenrate laut französischen Daten nur sehr schwach. Das Land kann diese Leistungen nicht selbst einführen, sondern nur über den Bundesrat werben.', 'gemischt', 'https://journals.openedition.org/economiepublique/279', 'land', null, true, 'blind'),
  (9581, 24, 'Hilfen für Schwangere in Not- und Konfliktlagen ausbauen (Land)', 'Unterstützung kann Schwangeren in schwierigen Lagen helfen. Ob dadurch insgesamt mehr Kinder geboren werden, ist kaum untersucht und wohl nur ein kleiner Effekt.', 'offen', null, 'land', null, true, 'blind'),
  (9582, 24, 'Familienzentren und Familienberatung sichern und ausbauen (Land)', 'Stärkt die Infrastruktur für Familien vor Ort. Eine Wirkung auf die Geburtenzahl oder den Zuzug ist kaum untersucht und allenfalls indirekt.', 'offen', null, 'land', null, true, 'blind'),
  (9583, 24, 'Familiengründung in Landeskampagnen und Lehrplänen hervorheben (Land)', 'Kampagnen und Unterrichtsinhalte sind leicht umzusetzen. Eine Wirkung auf Kinderwunsch und Geburten ist nicht belegt, materielle Hürden bleiben bestehen.', 'offen', null, 'land', null, true, 'blind'),
  (9584, 24, 'Zuwanderung von Fachkräften erleichtern: schnellere Verfahren, Anerkennung, Anlaufstellen (Land)', 'Zuwanderung bremst die Alterung nachweislich, wenn auch ohne sie umzukehren. Schnellere Verfahren und Welcome Center erleichtern den Zuzug, das Aufenthaltsrecht regelt aber der Bund.', 'gemischt', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'land', null, true, 'blind'),
  (9585, 24, 'Integrationsangebote für Zugewanderte, auch im ländlichen Raum (Land)', 'Sprachkurse und Integrationsmittel können dazu beitragen, dass Zugewanderte bleiben. Die Wirkung auf die Bevölkerungsentwicklung ist indirekt, Integrationskurse finanziert zum Teil der Bund.', 'offen', null, 'land', null, true, 'blind'),
  (9586, 24, 'Für Zuzug ins Land und in ländliche Räume werben (Land)', 'Werbung und gute Lebensbedingungen können Zuzug anstoßen. Ohne passende Arbeitsplätze ist die Wirkung von Kampagnen aber kaum belegt.', 'offen', null, 'land', null, true, 'blind'),
  (9587, 24, 'Versorgung und Orte im ländlichen Raum an den demografischen Wandel anpassen (Land)', 'Dorfläden, zentrale Orte, Schulstandorte und Ehrenamt sichern die Versorgung schrumpfender Orte. Sie mildern Folgen der Alterung, ändern aber Geburten und Zuzug kaum.', 'offen', null, 'land', null, true, 'blind'),
  (9588, 24, 'Wohnungsleerstand in schrumpfenden Kommunen abbauen (Land)', 'Rückbau und Hilfen bei Leerstand stabilisieren Wohnungsunternehmen und Ortsbilder. Das ist eine Reaktion auf die Schrumpfung, deren Ursache bleibt unberührt.', 'offen', null, 'land', null, true, 'blind'),
  (9589, 24, 'Bezahlbare Wohnheimplätze für Auszubildende und Studierende schaffen (Land)', 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'offen', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'land', null, true, 'blind'),
  (9590, 24, 'Hochschulen allgemein besser finanzieren und sanieren (Land)', 'Gut ausgestattete Hochschulen machen den Studienort attraktiver. Ohne Bezug zu ländlichen Standorten ist die Wirkung auf die Abwanderung junger Menschen aber indirekt, und die Kosten sind hoch.', 'offen', null, 'land', null, true, 'blind'),
  (9591, 24, 'Studienangebote und Hochschulstandorte im Land, auch im ländlichen Raum, ausbauen (Land)', 'Viele Absolventen, besonders von Fachhochschulen, bleiben in der Region ihres Studiums oder kehren zurück. Entscheidend sind aber passende Jobs vor Ort, und neue Standorte brauchen Jahre.', 'belegt', 'https://www.bmluk.gv.at/themen/landwirtschaft/bildung-forschung/Online-Fachzeitschrift-Laendlicher-Raum/archiv/2013/Hochqualifizierte.html', 'land', null, true, 'blind'),
  (9592, 24, 'Studienstandort durch neue Angebote, Internationalisierung und Marketing attraktiver machen (Land)', 'Kann mehr Studierende ins Land holen. Ob sie nach dem Studium bleiben, hängt von Arbeitsplätzen ab, die Wirkung auf die Abwanderung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9593, 24, 'Absolventen über Beratung, Vernetzung mit Betrieben und Übergangshilfen im Land halten (Land)', 'Kontakte zu regionalen Betrieben schon im Studium fördern den Verbleib. Die Programme sind günstig, ihre Wirkung ist aber kaum evaluiert, und am Ende entscheiden passende Stellen.', 'offen', null, 'land', null, true, 'blind'),
  (9594, 24, 'Stipendien und Vergütungen mit Verbleibs- oder Rückkehrpflicht (Land)', 'Die Verpflichtung bindet Geförderte direkt für einige Jahre an das Land. Es geht aber um wenige Personen, und ob sie langfristig bleiben, ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9595, 24, 'Rückkehrprogramme für abgewanderte Fachkräfte (Land)', 'Rückkehr kommt vor, vor allem aus familiären Gründen, und Rückkehrende ziehen oft aufs Land. Die Wirkung gezielter Programme und Prämien ist kaum untersucht.', 'offen', 'https://www.l-iz.de/politik/kassensturz/2013/12/Abwanderer-kehren-haeufiger-nach-Ostdeutschland-zurueck-52723', 'land', null, true, 'blind'),
  (9596, 24, 'Berufsschulen und Ausbildungszentren ausstatten und fördern (Land)', 'Gute Ausstattung macht die Ausbildung im Land attraktiver. Ohne Zusage für Standorte in der Fläche hilft das gegen die Abwanderung junger Menschen nur am Rand.', 'offen', null, 'land', null, true, 'blind'),
  (9597, 24, 'Pflichtpraktika und Betriebsbesuche in der Schule zur Bindung an regionale Betriebe (Land)', 'Frühe Kontakte zu Betrieben vor Ort können junge Menschen an die Region binden. Belastbare Belege zur Wirkung auf den Verbleib fehlen.', 'offen', null, 'land', null, true, 'blind'),
  (9598, 24, 'Allgemeine Regionalförderung gegen Abwanderung, etwa Stärkung von Mittelzentren und Behördenansiedlung (Land)', 'Mehr Arbeitsplätze und Angebote in kleineren Zentren können Abwanderung bremsen. Die Zusagen sind meist unbestimmt, und die Wirkung ist kaum belegt.', 'offen', null, 'land', null, true, 'blind'),
  (9599, 24, 'Kommunalen Finanzausgleich aufstocken und bedarfsgerecht reformieren (Land)', 'Mehr und verlässlichere Zuweisungen setzen direkt an der knappen Finanzlage an, die laut Umfragen Investitionen bremst. Das belastet aber den Landeshaushalt und hängt von der Höhe ab.', 'belegt', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'land', null, true, 'blind'),
  (9600, 24, 'Pauschale Zuweisungen statt kleinteiliger Förderprogramme, Förderverfahren vereinfachen (Land)', 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'belegt', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'land', null, true, 'blind'),
  (9601, 24, 'Dauerhaftes kommunales Investitionsprogramm (Land)', 'Zusätzliche Investitionsmittel verringern den Investitionsrückstand der Kommunen. Programme sind aber oft zweckgebunden und an Personal für die Umsetzung gebunden.', 'offen', null, 'land', null, true, 'blind'),
  (9602, 24, 'Altschuldenfonds bzw. Entschuldungsprogramm für überschuldete Kommunen (Land)', 'Senkt Zins- und Tilgungslasten und schafft Spielraum, Erfahrungen gibt es etwa mit der Hessenkasse. Unabhängige Wirkungsstudien fehlen, und neue Schulden müssen verhindert werden.', 'offen', null, 'land', null, true, 'blind'),
  (9603, 24, 'Konnexität strikt anwenden: übertragene Aufgaben vollständig ausgleichen (Land)', 'Verhindert neue ungedeckte Kosten bei den Kommunen und setzt an einer Ursache ihrer Finanznot an. Ein Ausgleich bestehender Aufgaben kostet das Land viel, die Wirkung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9604, 24, 'Planungs- und Genehmigungsverfahren beschleunigen, mit Fristen und Genehmigungsfiktion (Land)', 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'offen', null, 'land', null, true, 'blind'),
  (9605, 24, 'Genehmigungs- und Verwaltungsverfahren digitalisieren (Land)', 'Digitale Verfahren können Personalmangel in Verwaltungen teilweise ausgleichen. Die Umsetzung dauert erfahrungsgemäß lange, und die Wirkung ist kaum gemessen.', 'offen', null, 'land', null, true, 'blind'),
  (9606, 24, 'Bürokratie und Vorgaben für Kommunen abbauen, Entscheidungsspielräume erweitern (Land)', 'Weniger Vorgaben entlasten die Verwaltungen der Kommunen. Die Zusagen sind meist unbestimmt, und an der Finanzlage ändern sie wenig.', 'offen', null, 'land', null, true, 'blind'),
  (9607, 24, 'Mehr Personal und Kapazität für kommunale Bau- und Planungsverwaltungen (Land)', 'Unterbesetzte Bauämter gelten laut Kommunalumfragen als zentrales Hemmnis für Investitionen. Mehr Personal setzt daran an, ist auf dem Arbeitsmarkt aber schwer zu gewinnen.', 'belegt', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'land', null, true, 'blind'),
  (9608, 24, 'Personalgewinnung in der öffentlichen Verwaltung allgemein verbessern (Land)', 'Kann den Personalmangel in der Verwaltung lindern. Ein Bezug zu kommunalen Bau- und Planungsaufgaben ist nur teilweise gegeben, die Wirkung ist kaum belegt.', 'offen', null, 'land', null, true, 'blind'),
  (9609, 24, 'Interkommunale Zusammenarbeit fördern und erleichtern (Land)', 'Gemeinsame Verwaltungseinheiten können Personal und Kosten bündeln. Große empirische Studien zu Einsparungen fehlen für Deutschland.', 'offen', null, 'land', null, true, 'blind'),
  (9610, 24, 'Vergaberecht vereinfachen und Wertgrenzen für Direktvergaben erhöhen (Land)', 'Höhere Wertgrenzen verkürzen Vergabeverfahren in den Kommunen. Dagegen sprechen weniger Wettbewerb und mögliche höhere Preise, die Wirkung ist kaum untersucht.', 'offen', null, 'land', null, true, 'blind'),
  (9611, 24, 'Höheren kommunalen Steueranteil und Gemeindefinanzreform auf Bundesebene einfordern (Land)', 'Eine höhere Steuerbeteiligung würde die Finanzbasis der Kommunen dauerhaft stärken. Das Land kann das aber nur über Bundesrat und Bund erreichen.', 'offen', null, 'land', null, true, 'blind'),
  (9612, 24, 'Kommunale Steuern umbauen, etwa Gemeindewirtschaftsteuer oder Zuschlagsmodell (Land)', 'Ein Umbau kann die Einnahmen der Kommunen verbreitern oder stabilisieren. Die Gesetzgebung liegt beim Bund, und das Aufkommen hängt von der Ausgestaltung ab.', 'offen', null, 'land', null, true, 'blind'),
  (9613, 24, 'Entschuldung der Kommunen durch den Bund einfordern (Land)', 'Ein Schuldenschnitt würde den Kommunen große Spielräume verschaffen. Das Land kann ihn nicht allein umsetzen, die Finanzierung durch den Bund ist offen.', 'offen', null, 'land', null, true, 'blind'),
  (9614, 24, 'Ausbau der Kita-Plätze mit Bundesbeteiligung (Bund)', 'Mehr Krippenplätze erhöhen laut Studien die Geburtenrate leicht. Zuständig sind die Länder, der Bund kann über Investitionsprogramme beitragen, und es fehlt Personal.', 'belegt', 'https://ifo.de/publikationen/2013/working-paper/does-expanding-public-child-care-encourage-fertility-county-level', 'bund', null, true, 'blind'),
  (9615, 24, 'Familien über Kindergeld und Steuer entlasten, etwa Familiensplitting (Bund)', 'Entlastet Familien finanziell. Studien zum französischen Familiensplitting finden aber nur sehr schwache Effekte auf die Geburten, und die Kosten sind hoch.', 'gemischt', 'https://journals.openedition.org/economiepublique/279', 'bund', null, true, 'blind'),
  (9616, 24, 'Elterngeld und Freistellung nach der Geburt ausweiten (Bund)', 'Studien zum Elterngeld zeigen positive Geburteneffekte vor allem bei höheren Einkommen und Akademikerinnen, insgesamt aber kleine Effekte. Die Ausweitung kostet viel.', 'gemischt', 'https://ideas.repec.org/a/diw/diwvjh/83-1-9.html', 'bund', null, true, 'blind'),
  (9617, 24, 'Kinderwunschbehandlungen besser finanzieren, auch über die Krankenkassen (Bund)', 'Nach den Kürzungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Bessere Finanzierung wirkt also, betrifft aber nur einen kleinen Teil der Geburten, und Kosten fallen an.', 'belegt', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'bund', null, true, 'blind'),
  (9618, 24, 'Fachkräfteeinwanderung erleichtern und Verfahren modernisieren (Bund)', 'Zuwanderung bremst die Alterung nachweislich, kehrt sie aber nicht um. Ob die Fachkräfte in strukturschwache Regionen ziehen und bleiben, ist offen.', 'gemischt', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'bund', null, true, 'blind'),
  (9619, 24, 'Bundesförderung für Wohnheime für Studierende und Auszubildende verstetigen (Bund)', 'Das Programm läuft bereits und senkt die Wohnkosten in Ausbildung und Studium. Ob das die Abwanderung aus ländlichen Regionen bremst, ist kaum untersucht.', 'offen', null, 'bund', null, true, 'blind'),
  (9620, 24, 'Bundesbeteiligung an Hochschulbau und Hochschulfinanzierung in allen Regionen (Bund)', 'Bessere Hochschulen stärken Studienorte auch außerhalb der Metropolen. Die Wirkung auf die Abwanderung ist indirekt, und es braucht Vereinbarungen mit den Ländern.', 'offen', null, 'bund', null, true, 'blind'),
  (9621, 24, 'Führerscheinkosten für junge Menschen senken oder fördern (Bund)', 'Mobilität erleichtert im ländlichen Raum den Weg zu Ausbildung und Arbeit ohne Umzug. Die Wirkung auf die Abwanderung ist nicht untersucht, es gibt Mitnahmeeffekte.', 'offen', null, 'bund', null, true, 'blind'),
  (9622, 24, 'Strukturpolitik für ländliche Regionen und kleine Städte (Bund)', 'Investitionen außerhalb der Metropolen können Regionen attraktiver machen. Die Zusagen sind unbestimmt, und die Wirkung auf die Abwanderung junger Menschen ist kaum belegt.', 'offen', null, 'bund', null, true, 'blind'),
  (9623, 24, 'Wohneigentum junger Familien in kleinen Städten und Dörfern fördern (Bund)', 'Kann junge Familien im Ort halten und Leerstand nutzen. Die Wirkung auf die Abwanderung ist kaum untersucht, und Einheimischenmodelle müssen EU-Recht beachten.', 'offen', null, 'bund', null, true, 'blind'),
  (9624, 24, 'Berufsorientierung an Schulen in Kooperation mit Betrieben stärken (Bund)', 'Bessere Orientierung kann die Passung von Ausbildungswünschen und Stellen verbessern. Belastbare Wirkungsnachweise auf den Übergang in Ausbildung fehlen, Schulen sind Ländersache.', 'offen', null, 'bund', null, true, 'blind'),
  (9625, 24, 'Jugendberufsagenturen flächendeckend einrichten und stärken (Bund)', 'Eine zentrale Anlaufstelle setzt an der Vermittlung zwischen Bewerbern und Stellen an, Hamburg meldet mehr direkte Übergänge. Kausale Wirkungsstudien fehlen bisher.', 'offen', 'https://www.bibb.de/de/177236.php', 'bund', null, true, 'blind'),
  (9626, 24, 'Ausbildungsumlage bzw. Ausbildungsfonds (Bund)', 'In der Pflege brachte die Umlage deutlich mehr Auszubildende. Für allgemeine Umlagen fehlen Belege, sie wirken nur bei echtem Stellenmangel, nicht bei Besetzungsproblemen.', 'gemischt', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2026/heft/3/beitrag/zur-diskussion-einer-ausbildungsumlage-fuer-die-duale-berufsausbildung.html', 'bund', null, true, 'blind'),
  (9627, 24, 'Ausbildungsgarantie mit außerbetrieblichen Plätzen und Assistierter Ausbildung ausbauen (Bund)', 'Österreich gilt mit seiner Ausbildungsgarantie als Vorbild, wenn betriebliche Plätze fehlen. Wirkungsdaten sind begrenzt, und außerbetriebliche Plätze sind teuer.', 'gemischt', 'https://www.bertelsmann-stiftung.de/de/publikationen/publikation/did/die-ausbildungsgarantie-in-oesterreich-all', 'bund', null, true, 'blind'),
  (9628, 24, 'Kommunen mehr Bundesmittel für Investitionen und Grundausstattung geben (Bund)', 'Zusätzliche Mittel setzen am Rekord-Investitionsrückstand der Kommunen an. Der Bund kann nur über Länder oder Sonderprogramme fördern, und die Mittel fließen wegen Personalmangel oft langsam ab.', 'belegt', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'bund', null, true, 'blind'),
  (9629, 24, 'Bundesförderprogramme vereinfachen und ohne Eigenanteil öffnen (Bund)', 'Kommunen nennen Antragsaufwand und Eigenanteile als Hürde, finanzschwache Kommunen gehen oft leer aus. Die Vereinfachung hilft gezielt, die Mittel bleiben aber begrenzt.', 'belegt', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'bund', null, true, 'blind'),
  (9630, 24, 'Bundesweite Lösung für kommunale Altschulden (Bund)', 'Eine Entschuldung würde hoch verschuldeten Kommunen Spielraum verschaffen. Dafür braucht es voraussichtlich eine Grundgesetzänderung und eine Einigung mit den Ländern, die Wirkung ist kaum evaluiert.', 'offen', null, 'bund', null, true, 'blind'),
  (9631, 24, 'Konnexität zwischen Bund und Kommunen konsequent einhalten (Bund)', 'Würde neue ungedeckte Lasten verhindern. Der Bund darf Kommunen keine Aufgaben direkt übertragen, eine Ausgleichspflicht würde eine Verfassungsänderung erfordern, und die Zusage ist unbestimmt.', 'offen', null, 'bund', null, true, 'blind'),
  (9632, 24, 'Planungs- und Genehmigungsverfahren beschleunigen und digitalisieren (Bund)', 'Schnellere Verfahren entlasten Behörden und Kommunen bei Bauprojekten. Wirkungsstudien zur Genehmigungsfiktion fehlen, und an der Finanzlage der Kommunen ändert sich wenig.', 'offen', null, 'bund', null, true, 'blind'),
  (9633, 24, 'Kommunen an Erträgen von Wind- und Solaranlagen beteiligen (Bund)', 'Verschafft Standortgemeinden zusätzliche Einnahmen. Das betrifft nur Kommunen mit Anlagen, die Beträge sind begrenzt.', 'offen', null, 'bund', null, true, 'blind')
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 24 and id not in (9575, 9576, 9577, 9578, 9579, 9580, 9581, 9582, 9583, 9584, 9585, 9586, 9587, 9588, 9589, 9590, 9591, 9592, 9593, 9594, 9595, 9596, 9597, 9598, 9599, 9600, 9601, 9602, 9603, 9604, 9605, 9606, 9607, 9608, 9609, 9610, 9611, 9612, 9613, 9614, 9615, 9616, 9617, 9618, 9619, 9620, 9621, 9622, 9623, 9624, 9625, 9626, 9627, 9628, 9629, 9630, 9631, 9632, 9633);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (9634, 24, 11, null, 'Kindergeld anheben und künftig automatisch nach der Geburt auszahlen', '{2402}', 9615, 1, 2, null, 'Entlastet Familien finanziell. Studien zum französischen Familiensplitting finden aber nur sehr schwache Effekte auf die Geburten, und die Kosten sind hoch.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=63', 'https://journals.openedition.org/economiepublique/279', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9635, 24, 11, null, 'Zuzug von nach 1993 geborenen Angehörigen von Spätaussiedlern ermöglichen', '{2402}', null, 1, 3, null, 'Ermöglicht zusätzlichen Zuzug von Angehörigen von Spätaussiedlern. Die Zahl ist voraussichtlich klein und verteilt sich nicht gezielt auf strukturschwache Regionen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=60', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9636, 24, 11, null, 'Digitale Bundesagentur für Einwanderung von Fachkräften einrichten', '{2402}', 9618, 2, 3, null, 'Zuwanderung bremst die Alterung nachweislich, kehrt sie aber nicht um. Ob die Fachkräfte in strukturschwache Regionen ziehen und bleiben, ist offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=15', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9637, 24, 11, null, 'Hochschulen und Forschungseinrichtungen in allen Regionen stärken', '{2401}', 9620, 1, 2, null, 'Bessere Hochschulen stärken Studienorte auch außerhalb der Metropolen. Die Wirkung auf die Abwanderung ist indirekt, und es braucht Vereinbarungen mit den Ländern.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=27', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9638, 24, 11, null, 'Berufsorientierung in allen Schulformen mit bestehenden Maßnahmen abstimmen', '{2403}', 9624, 1, 2, null, 'Bessere Orientierung kann die Passung von Ausbildungswünschen und Stellen verbessern. Belastbare Wirkungsnachweise auf den Übergang in Ausbildung fehlen, Schulen sind Ländersache.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=67', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9639, 24, 11, null, 'Allianz für Aus- und Weiterbildung fortführen', '{2403}', null, 1, 3, null, 'Die Allianz koordiniert Wirtschaft, Gewerkschaften und Politik bei der Ausbildung. Sie besteht bereits, sodass ihre Fortführung kaum zusätzliche Wirkung erwarten lässt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=66', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9640, 24, 11, null, 'Planungs- und Baugenehmigungsverfahren digitalisieren und beschleunigen', '{2404}', 9632, 1, 3, null, 'Schnellere Verfahren entlasten Behörden und Kommunen bei Bauprojekten. Wirkungsstudien zur Genehmigungsfiktion fehlen, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9641, 24, 11, null, 'Grundsatz der Konnexität: Wer eine Leistung veranlasst, zahlt die Finanzierung', '{2404}', 9631, 1, 1, null, 'Würde neue ungedeckte Lasten verhindern. Der Bund darf Kommunen keine Aufgaben direkt übertragen, eine Ausgleichspflicht würde eine Verfassungsänderung erfordern, und die Zusage ist unbestimmt.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=76', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9642, 24, 11, 'BE', 'Sanierungsrückstau der Hochschulen abbauen und die Hochschulbaugesellschaft für schnellere Bauprojekte weiterentwickeln', '{2401}', 9590, 1, 2, null, 'Gut ausgestattete Hochschulen machen den Studienort attraktiver. Ohne Bezug zu ländlichen Standorten ist die Wirkung auf die Abwanderung junger Menschen aber indirekt, und die Kosten sind hoch.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=49', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9643, 24, 11, 'BE', 'Wohnheime für Auszubildende aufbauen, in Zusammenarbeit mit landeseigenen Betrieben', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=41', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9644, 24, 11, 'BE', 'Studienbeiträge in begrenztem Umfang für bestimmte Gruppen ermöglichen, um Hochschulen Spielraum zu geben', '{2401}', null, 0, 2, null, 'Mehreinnahmen könnten die Lehre verbessern. Gebühren machen den Studienort für die betroffenen Gruppen aber eher unattraktiver, die Einnahmen sind gering.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=49', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9645, 24, 11, 'BE', 'Berliner Willkommenszentrum weiterentwickeln und mit Willkommensmanagern Verfahren für Fachkräfte beschleunigen', '{2402}', 9584, 2, 2, null, 'Zuwanderung bremst die Alterung nachweislich, wenn auch ohne sie umzukehren. Schnellere Verfahren und Welcome Center erleichtern den Zuzug, das Aufenthaltsrecht regelt aber der Bund.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=41', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9646, 24, 11, 'BE', 'Ausbau flexibler und längerer Betreuungsangebote für Kinder mit solider Finanzierung sichern', '{2402}', 9575, 2, 2, null, 'Studien aus Deutschland zeigen, dass mehr Krippenplätze die Geburtenrate leicht erhöhen, vor allem bei zweiten und dritten Kindern. Der Effekt ist begrenzt, und es fehlen Fachkräfte.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=108', 'https://ifo.de/publikationen/2013/working-paper/does-expanding-public-child-care-encourage-fertility-county-level', 'belegt', '2026-10-11', false, true, 'blind'),
  (9647, 24, 11, 'BE', 'Bezirke auskömmlich, transparent und verlässlich finanzieren, damit ihre Handlungsfähigkeit gestärkt wird', '{2404}', 9599, 2, 2, null, 'Mehr und verlässlichere Zuweisungen setzen direkt an der knappen Finanzlage an, die laut Umfragen Investitionen bremst. Das belastet aber den Landeshaushalt und hängt von der Höhe ab.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=89', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9648, 24, 11, 'BE', 'Genehmigungs- und Entscheidungszeiten in der Verwaltung spürbar verkürzen, unter anderem durch Genehmigungsfiktionen', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=42', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9649, 24, 11, 'BE', 'Personalgewinnung und -bindung für die Landesverwaltung fortführen', '{2404}', 9608, 1, 2, null, 'Kann den Personalmangel in der Verwaltung lindern. Ein Bezug zu kommunalen Bau- und Planungsaufgaben ist nur teilweise gegeben, die Wirkung ist kaum belegt.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=90', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9650, 24, 11, 'MV', 'Staatlichen Hochschulstandort in Schwerin schaffen, um junge Menschen in der Region zu binden', '{2401}', 9591, 2, 2, null, 'Viele Absolventen, besonders von Fachhochschulen, bleiben in der Region ihres Studiums oder kehren zurück. Entscheidend sind aber passende Jobs vor Ort, und neue Standorte brauchen Jahre.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=65', 'https://www.bmluk.gv.at/themen/landwirtschaft/bildung-forschung/Online-Fachzeitschrift-Laendlicher-Raum/archiv/2013/Hochqualifizierte.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9651, 24, 11, 'MV', 'Programm „Stay in MV“ mit Stipendien, die an einen Mindestverbleib im Land gekoppelt sind, zur Bindung von Talenten', '{2401}', 9594, 1, 2, null, 'Die Verpflichtung bindet Geförderte direkt für einige Jahre an das Land. Es geht aber um wenige Personen, und ob sie langfristig bleiben, ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=69', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9652, 24, 11, 'MV', 'Studienangebote ausbauen und das Studieren flexibler machen, um den Studienstandort attraktiver zu machen', '{2401}', 9592, 1, 3, null, 'Kann mehr Studierende ins Land holen. Ob sie nach dem Studium bleiben, hängt von Arbeitsplätzen ab, die Wirkung auf die Abwanderung ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=68', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9653, 24, 11, 'MV', 'Bezahlbare Wohnheimplätze schaffen und Wohnungen für Studierende in der Landeswohnungsbauförderung schwerpunktmäßig fördern', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=68', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9654, 24, 11, 'MV', 'Mindestens 25 Landarztstudienplätze im EU-Ausland mit Rückkehrverpflichtung in die Region', '{2401}', 9594, 1, 2, null, 'Die Verpflichtung bindet Geförderte direkt für einige Jahre an das Land. Es geht aber um wenige Personen, und ob sie langfristig bleiben, ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=72', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9655, 24, 11, 'MV', 'Vergütung im Praktischen Jahr am BaföG-Höchstsatz, um die regionale Bindung von Medizinstudierenden zu stärken', '{2401}', 9594, 1, 2, null, 'Die Verpflichtung bindet Geförderte direkt für einige Jahre an das Land. Es geht aber um wenige Personen, und ob sie langfristig bleiben, ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=72', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9656, 24, 11, 'MV', 'Übergangsregelungen, damit erfolgreiche ausländische Promovierende langfristig im Land bleiben', '{2401}', 9593, 1, 3, null, 'Kontakte zu regionalen Betrieben schon im Studium fördern den Verbleib. Die Programme sind günstig, ihre Wirkung ist aber kaum evaluiert, und am Ende entscheiden passende Stellen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=67', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9657, 24, 11, 'MV', 'Marketing der Hochschulen verstärken, um die Studierendenzahl zu stabilisieren', '{2401}', 9592, 1, 3, null, 'Kann mehr Studierende ins Land holen. Ob sie nach dem Studium bleiben, hängt von Arbeitsplätzen ab, die Wirkung auf die Abwanderung ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=69', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9658, 24, 11, 'MV', 'Gesetz für den ländlichen Raum einsetzen, das Infrastruktur, Versorgung und Wirtschaftsperspektiven verbindlich regelt', '{2401}', 9598, 1, 2, null, 'Mehr Arbeitsplätze und Angebote in kleineren Zentren können Abwanderung bremsen. Die Zusagen sind meist unbestimmt, und die Wirkung ist kaum belegt.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=121', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9659, 24, 11, 'MV', 'Familien beim Ersterwerb von Wohneigentum mit 15.000 Euro je Kind unterstützen, auch für Kinder, die künftig geboren werden', '{2402}', null, 1, 2, null, 'Ein Zuschuss je Kind beim Eigentumserwerb entlastet Familien deutlich. Eine Wirkung auf die Geburtenzahl ist nicht belegt, und es gibt Mitnahmeeffekte bei hohen Kosten.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=19', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9660, 24, 11, 'MV', 'Genehmigungsverfahren durch eine Drei-Monats-Genehmigungsfiktion mit Stichtagen verbindlicher machen', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=11', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9661, 24, 11, 'MV', 'Infrastrukturpauschale des Landes für Kommunen auf mindestens 200 Millionen Euro anheben', '{2404}', 9600, 2, 3, null, 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=41', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9662, 24, 11, 'MV', 'Konnexitätsprinzip uneingeschränkt anwenden und bestehende Aufgabenübertragungen an Kommunen nachfinanzieren', '{2404}', 9603, 2, 2, null, 'Verhindert neue ungedeckte Kosten bei den Kommunen und setzt an einer Ursache ihrer Finanznot an. Ein Ausgleich bestehender Aufgaben kostet das Land viel, die Wirkung ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=41', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9663, 24, 11, 'MV', 'Entschuldungsprogramme für hoch verschuldete Kommunen fortführen und weiterentwickeln', '{2404}', 9602, 2, 2, null, 'Senkt Zins- und Tilgungslasten und schafft Spielraum, Erfahrungen gibt es etwa mit der Hessenkasse. Unabhängige Wirkungsstudien fehlen, und neue Schulden müssen verhindert werden.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=42', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9664, 24, 11, 'MV', 'Förderprogramme für Kommunen vereinfachen, pauschalieren und standardisieren', '{2404}', 9600, 2, 3, null, 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=41', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9665, 24, 11, 'MV', 'Überflüssige Vorschriften im Verwaltungsalltag beseitigen', '{2404}', 9606, 1, 3, null, 'Weniger Vorgaben entlasten die Verwaltungen der Kommunen. Die Zusagen sind meist unbestimmt, und an der Finanzlage ändern sie wenig.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=42', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9666, 24, 11, 'MV', 'Erweiterte interkommunale Zusammenarbeit unterstützen, etwa im Personalbereich oder bei IT-Sicherheit', '{2404}', 9609, 1, 3, null, 'Gemeinsame Verwaltungseinheiten können Personal und Kosten bündeln. Große empirische Studien zu Einsparungen fehlen für Deutschland.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=41', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9667, 24, 11, 'MV', 'Vergabeverfahren prüfen und vereinfachen, etwa durch Direktaufträge oder modulare Ausschreibungen', '{2404}', 9610, 1, 3, null, 'Höhere Wertgrenzen verkürzen Vergabeverfahren in den Kommunen. Dagegen sprechen weniger Wettbewerb und mögliche höhere Preise, die Wirkung ist kaum untersucht.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=19', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9668, 24, 11, 'MV', 'Regelungen für Umbauten und Nebenanlagen vereinfachen und Bauvorhaben häufiger genehmigungs- oder verfahrensfrei stellen', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=19', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9669, 24, 11, 'MV', 'Lösungsorientierte Prüfung bei Bau-, Infrastruktur- und Förderanträgen kommunaler Träger durch Genehmigungs- und Prüfbehörden', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=43', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9670, 24, 11, 'MV', 'Straßenbauverwaltung des Landes finanziell, personell und organisatorisch stärken', '{2404}', 9608, 1, 2, null, 'Kann den Personalmangel in der Verwaltung lindern. Ein Bezug zu kommunalen Bau- und Planungsaufgaben ist nur teilweise gegeben, die Wirkung ist kaum belegt.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=114', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9671, 24, 11, 'MV', 'Vorlagen für die standardisierte Umsetzung von Bauprojekten bereitstellen, um Kommunen fachlich zu unterstützen', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=113', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9672, 24, 11, 'MV', 'Prozesse der staatlichen Bau- und Liegenschaftsverwaltung digitalisieren und mit Künstlicher Intelligenz effizienter machen', '{2404}', 9605, 1, 2, null, 'Digitale Verfahren können Personalmangel in Verwaltungen teilweise ausgleichen. Die Umsetzung dauert erfahrungsgemäß lange, und die Wirkung ist kaum gemessen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=113', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9673, 24, 11, 'MV', 'Kommunen direkte Planungssicherheit für Infrastrukturprojekte geben, unterstützt durch beschleunigte Genehmigungsverfahren', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=122', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9674, 24, 11, 'ST', 'Hochschulen sollen Studierende während des Studiums an die Region binden, besonders internationale Studierende', '{2401}', 9593, 1, 3, null, 'Kontakte zu regionalen Betrieben schon im Studium fördern den Verbleib. Die Programme sind günstig, ihre Wirkung ist aber kaum evaluiert, und am Ende entscheiden passende Stellen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=76', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9675, 24, 11, 'ST', 'Grunderwerbsteuerbefreiung beim ersten selbstgenutzten Wohneigentum im ländlichen Raum, besonders für junge Familien', '{2401}', null, 1, 1, null, 'Kann jungen Familien den Erwerb im ländlichen Raum erleichtern. Die Länder bestimmen nur den Steuersatz, eine Befreiung braucht eine Öffnung im Bundesrecht, und es gibt Mitnahmeeffekte.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=31', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9676, 24, 11, 'ST', 'Ausbildungszentren und berufsbildende Schulen gezielt fördern', '{2401}', 9596, 1, 3, null, 'Gute Ausstattung macht die Ausbildung im Land attraktiver. Ohne Zusage für Standorte in der Fläche hilft das gegen die Abwanderung junger Menschen nur am Rand.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=33', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9677, 24, 11, 'ST', 'Auch Paare mit unerfülltem Kinderwunsch finanziell unterstützen', '{2402}', 9577, 2, 3, null, 'Nach den Kürzungen der Kassenleistungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Zuschüsse wirken also, aber nur für einen kleinen Teil der Geburten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=31', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9678, 24, 11, 'ST', 'Innovationen unterstützen, damit Dörfer trotz des demografischen Wandels lebens- und lebenswert bleiben', '{2402}', 9587, 1, 2, null, 'Dorfläden, zentrale Orte, Schulstandorte und Ehrenamt sichern die Versorgung schrumpfender Orte. Sie mildern Folgen der Alterung, ändern aber Geburten und Zuzug kaum.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=39', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9679, 24, 11, 'ST', 'Finanzausstattung der Kommunen sichern und den Finanzausgleich ab 2027 neu regeln', '{2404}', 9599, 2, 2, null, 'Mehr und verlässlichere Zuweisungen setzen direkt an der knappen Finanzlage an, die laut Umfragen Investitionen bremst. Das belastet aber den Landeshaushalt und hängt von der Höhe ab.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=79', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9680, 24, 11, 'ST', 'Planungs- und Genehmigungsverfahren beschleunigen, mit zeitlicher Begrenzung der Bearbeitung', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=55', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9681, 24, 11, 'ST', 'Genehmigungs- und Vergabeverfahren vollständig digitalisieren, Genehmigungsfiktion einführen', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=55', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9682, 24, 11, 'ST', 'Mehr Pauschalzahlungen für Kommunen, Vereinfachung von Förderverfahren und Experimentierklauseln', '{2404}', 9600, 2, 3, null, 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=10', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9683, 24, 11, 'ST', 'Interkommunale Zusammenarbeit fördern', '{2404}', 9609, 1, 3, null, 'Gemeinsame Verwaltungseinheiten können Personal und Kosten bündeln. Große empirische Studien zu Einsparungen fehlen für Deutschland.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=10', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9684, 24, 11, 'ST', 'Doppelzuständigkeiten aufheben, um kommunale Eigenverantwortung zu stärken (Grenzfall)', '{2404}', 9606, 1, 3, null, 'Weniger Vorgaben entlasten die Verwaltungen der Kommunen. Die Zusagen sind meist unbestimmt, und an der Finanzlage ändern sie wenig.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=55', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9685, 24, 12, null, 'Kleine Städte als Ankerpunkte für wirtschaftliche, kulturelle und soziale Netzwerke entwickeln, um die regionale Entwicklung zu fördern', '{2401}', 9622, 1, 2, null, 'Investitionen außerhalb der Metropolen können Regionen attraktiver machen. Die Zusagen sind unbestimmt, und die Wirkung auf die Abwanderung junger Menschen ist kaum belegt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=52', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9686, 24, 12, null, 'Programm „Jung kauft Alt“ verstetigen und ausbauen; Eigentumsförderung für junge Familien, besonders in kleinen Städten und ländlichen Regionen', '{2401}', 9623, 1, 3, null, 'Kann junge Familien im Ort halten und Leerstand nutzen. Die Wirkung auf die Abwanderung ist kaum untersucht, und Einheimischenmodelle müssen EU-Recht beachten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9687, 24, 12, null, 'Einheimischen-Modelle: ortsansässigen Familien vergünstigtes Bauland anbieten, damit sie in ihrer Heimatgemeinde Eigentum erwerben können', '{2401}', 9623, 1, 3, null, 'Kann junge Familien im Ort halten und Leerstand nutzen. Die Wirkung auf die Abwanderung ist kaum untersucht, und Einheimischenmodelle müssen EU-Recht beachten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9688, 24, 12, null, 'Mittel für Studierenden- und Azubi-Wohnheime verstetigen und erhöhen; WG-Zimmer für Studierende und Azubis möglichst höchstens 400 Euro', '{2401}', 9619, 1, 3, null, 'Das Programm läuft bereits und senkt die Wohnkosten in Ausbildung und Studium. Ob das die Abwanderung aus ländlichen Regionen bremst, ist kaum untersucht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=21', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9689, 24, 12, null, 'MobilitätsPass mit 500 Euro Guthaben für alle jungen Menschen im 17. Lebensjahr, etwa für Führerscheinkosten oder Bahntickets', '{2401}', 9621, 1, 3, null, 'Mobilität erleichtert im ländlichen Raum den Weg zu Ausbildung und Arbeit ohne Umzug. Die Wirkung auf die Abwanderung ist nicht untersucht, es gibt Mitnahmeeffekte.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9690, 24, 12, null, 'Arbeitgebern ermöglichen, steuer- und abgabenfrei einen Führerscheinzuschuss an Auszubildende und junge Beschäftigte zu zahlen', '{2401}', 9621, 1, 3, null, 'Mobilität erleichtert im ländlichen Raum den Weg zu Ausbildung und Arbeit ohne Umzug. Die Wirkung auf die Abwanderung ist nicht untersucht, es gibt Mitnahmeeffekte.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9691, 24, 12, null, 'Fahrausbildung samt Theorieunterricht reformieren, um die Kosten des Führerscheins zu senken', '{2401}', 9621, 1, 3, null, 'Mobilität erleichtert im ländlichen Raum den Weg zu Ausbildung und Arbeit ohne Umzug. Die Wirkung auf die Abwanderung ist nicht untersucht, es gibt Mitnahmeeffekte.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=36', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9692, 24, 12, null, 'Elterngeldanspruch ausweiten, mit zusätzlichen Monaten für beide Elternteile', '{2402}', 9616, 1, 2, null, 'Studien zum Elterngeld zeigen positive Geburteneffekte vor allem bei höheren Einkommen und Akademikerinnen, insgesamt aber kleine Effekte. Die Ausweitung kostet viel.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://ideas.repec.org/a/diw/diwvjh/83-1-9.html', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9693, 24, 12, null, 'Familienstartzeit: Väter oder Partnerinnen und Partner in den ersten zwei Wochen nach der Geburt bei voller Lohnfortzahlung freistellen', '{2402}', 9616, 1, 2, null, 'Studien zum Elterngeld zeigen positive Geburteneffekte vor allem bei höheren Einkommen und Akademikerinnen, insgesamt aber kleine Effekte. Die Ausweitung kostet viel.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=26', 'https://ideas.repec.org/a/diw/diwvjh/83-1-9.html', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9694, 24, 12, null, 'Umfassende Leerstand-Strategie für den ländlichen Raum mit Förderprogrammen, damit leerstehende Immobilien genutzt werden', '{2402}', null, 1, 2, null, 'Leerstehende Gebäude umzunutzen kann Orte im ländlichen Raum aufwerten und Zuzug erleichtern. Die Strategie ist unbestimmt, und eine Wirkung auf die Bevölkerungsentwicklung ist kaum belegt.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=53', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9695, 24, 12, null, 'Fachkräfteeinwanderungsgesetz unbürokratisch umsetzen und weiterentwickeln, damit Arbeitskräfte schneller nach Deutschland kommen', '{2402}', 9618, 2, 3, null, 'Zuwanderung bremst die Alterung nachweislich, kehrt sie aber nicht um. Ob die Fachkräfte in strukturschwache Regionen ziehen und bleiben, ist offen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9696, 24, 12, null, 'Ausbildungsgarantie fortsetzen', '{2403}', 9627, 2, 2, null, 'Österreich gilt mit seiner Ausbildungsgarantie als Vorbild, wenn betriebliche Plätze fehlen. Wirkungsdaten sind begrenzt, und außerbetriebliche Plätze sind teuer.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=13', 'https://www.bertelsmann-stiftung.de/de/publikationen/publikation/did/die-ausbildungsgarantie-in-oesterreich-all', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9697, 24, 12, null, 'Ausbildungsumlagen bzw. Fonds, vor allem branchenbezogen, dort wo unterhalb des Bedarfs ausgebildet wird', '{2403}', 9626, 2, 2, null, 'In der Pflege brachte die Umlage deutlich mehr Auszubildende. Für allgemeine Umlagen fehlen Belege, sie wirken nur bei echtem Stellenmangel, nicht bei Besetzungsproblemen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=13', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2026/heft/3/beitrag/zur-diskussion-einer-ausbildungsumlage-fuer-die-duale-berufsausbildung.html', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9698, 24, 12, null, 'Jugendberufsagenturen weiter stärken', '{2403}', 9625, 2, 3, null, 'Eine zentrale Anlaufstelle setzt an der Vermittlung zwischen Bewerbern und Stellen an, Hamburg meldet mehr direkte Übergänge. Kausale Wirkungsstudien fehlen bisher.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=13', 'https://www.bibb.de/de/177236.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9699, 24, 12, null, 'Duales Studium stärker fördern und Schutzrechte des Berufsbildungsgesetzes auf diesen Ausbildungsweg ausweiten', '{2403}', null, 1, 3, null, 'Ein gestärktes duales Studium erweitert praxisnahe Ausbildungswege. Am Mangel an passenden Ausbildungsplätzen für Schulabgänger ohne Abitur ändert das wenig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=16', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9700, 24, 12, null, 'Mindestausbildungsvergütung anheben', '{2403}', null, 1, 3, null, 'Eine höhere Vergütung macht die Ausbildung attraktiver und kann Besetzungsprobleme mindern. Sie kann kleine Betriebe aber vom Ausbilden abhalten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=15', null, 'gemischt', '2026-10-11', false, true, 'blind'),
  (9701, 24, 12, null, 'Lösung für die kommunalen Altschulden finden, auch für die Situation ostdeutscher Kommunen', '{2404}', 9630, 2, 1, null, 'Eine Entschuldung würde hoch verschuldeten Kommunen Spielraum verschaffen. Dafür braucht es voraussichtlich eine Grundgesetzänderung und eine Einigung mit den Ländern, die Wirkung ist kaum evaluiert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=18', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9702, 24, 12, null, 'Genehmigungsfiktion einführen: Anträge gelten als genehmigt, wenn die Behörde nicht innerhalb einer gesetzten Frist reagiert', '{2404}', 9632, 1, 3, null, 'Schnellere Verfahren entlasten Behörden und Kommunen bei Bauprojekten. Wirkungsstudien zur Genehmigungsfiktion fehlen, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9703, 24, 12, null, 'Digitalisierung der Bauverwaltung voranbringen und Bürokratieabbau fortsetzen', '{2404}', 9632, 1, 3, null, 'Schnellere Verfahren entlasten Behörden und Kommunen bei Bauprojekten. Wirkungsstudien zur Genehmigungsfiktion fehlen, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9704, 24, 12, null, 'Größere und modernere Kapazitäten zur Infrastrukturplanung der Kommunen, etwa für gemeinsamen Personaleinsatz', '{2404}', null, 1, 2, null, 'Gemeinsame Planungskapazitäten setzen am Personalmangel der Kommunen an. Der Bund kann sie nur fördern, die Zusage nennt weder Weg noch Umfang.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=18', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9705, 24, 12, 'BE', 'Bezahlbaren Wohnraum für Studierende ausbauen und den Anteil an Studierendenwohnungen verdoppeln.', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=44', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9706, 24, 12, 'BE', 'Das Förderprogramm für Kinderwunschbehandlungen (assistierte Reproduktion) wieder auflegen.', '{2402}', 9577, 2, 3, null, 'Nach den Kürzungen der Kassenleistungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Zuschüsse wirken also, aber nur für einen kleinen Teil der Geburten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=35', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9707, 24, 12, 'BE', 'Die landeseigenen Kita-Eigenbetriebe mit zusätzlichen Investitionsmitteln finanziell stabilisieren und dabei die schwankende Geburtenrate berücksichtigen.', '{2402}', 9576, 1, 3, null, 'Sichert vorhandene Betreuung bei sinkenden Kinderzahlen und hält Familien vor Ort. Neue Plätze entstehen nicht, deshalb ist kaum Wirkung auf die Geburten zu erwarten.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=37', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9708, 24, 12, 'BE', 'Das Finanzierungsmodell der Bezirke reformieren und das Konnexitätsprinzip konsequent umsetzen.', '{2404}', 9599, 2, 2, null, 'Mehr und verlässlichere Zuweisungen setzen direkt an der knappen Finanzlage an, die laut Umfragen Investitionen bremst. Das belastet aber den Landeshaushalt und hängt von der Höhe ab.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=61', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9709, 24, 12, 'BE', 'Planungsrechtliche Genehmigungen beschleunigen, mit KI-gestützter Digitalisierung in den Bauämtern.', '{2404}', 9605, 1, 2, null, 'Digitale Verfahren können Personalmangel in Verwaltungen teilweise ausgleichen. Die Umsetzung dauert erfahrungsgemäß lange, und die Wirkung ist kaum gemessen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=18', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9710, 24, 12, 'MV', 'Investitionen von 250 Mio. Euro bis 2037 in Berufsschulen und handwerkliche Bildungszentren für die duale Ausbildung', '{2401}', 9596, 1, 3, null, 'Gute Ausstattung macht die Ausbildung im Land attraktiver. Ohne Zusage für Standorte in der Fläche hilft das gegen die Abwanderung junger Menschen nur am Rand.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=70', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9711, 24, 12, 'MV', 'Förderung von Wohnheimplätzen an den Studienstandorten über das Bundesprogramm Junges Wohnen', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=72', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9712, 24, 12, 'MV', 'Umsetzung der Fachkräftestrategie und Fachkräfte-Offensive, um Fachkräfte und junge Menschen an das Land zu binden', '{2401}', 9593, 1, 3, null, 'Kontakte zu regionalen Betrieben schon im Studium fördern den Verbleib. Die Programme sind günstig, ihre Wirkung ist aber kaum evaluiert, und am Ende entscheiden passende Stellen.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=21', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9713, 24, 12, 'MV', 'Förderung von Kinderwunschbehandlungen', '{2402}', 9577, 2, 3, null, 'Nach den Kürzungen der Kassenleistungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Zuschüsse wirken also, aber nur für einen kleinen Teil der Geburten.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=30', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9714, 24, 12, 'MV', 'Fachkräfteservicezentrale für Anerkennung, Anwerbung und Zuzug von Fachkräften aus dem Ausland', '{2402}', 9584, 2, 2, null, 'Zuwanderung bremst die Alterung nachweislich, wenn auch ohne sie umzukehren. Schnellere Verfahren und Welcome Center erleichtern den Zuzug, das Aufenthaltsrecht regelt aber der Bund.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=22', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9715, 24, 12, 'MV', 'Öffentliche Investitionen in Kommunen in Schulen, Kultur, Sportstätten und Infrastruktur', '{2404}', 9601, 2, 2, null, 'Zusätzliche Investitionsmittel verringern den Investitionsrückstand der Kommunen. Programme sind aber oft zweckgebunden und an Personal für die Umsetzung gebunden.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=52', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9716, 24, 12, 'MV', 'Unterstützung der Kommunen bei der Nutzung des Bau-Turbo des Bundes für schnellere Wohnraumschaffung mit weniger Bürokratie', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=53', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9717, 24, 12, 'ST', 'Planungs- und Genehmigungsverfahren beschleunigen, Planfeststellungen reduzieren, Vergaberecht vereinfachen', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=44', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9718, 24, 12, 'ST', 'Bedarfsgerechten kommunalen Finanzausgleich einführen, der die tatsächlichen Aufgaben der Gemeinden abbildet', '{2404}', 9599, 2, 2, null, 'Mehr und verlässlichere Zuweisungen setzen direkt an der knappen Finanzlage an, die laut Umfragen Investitionen bremst. Das belastet aber den Landeshaushalt und hängt von der Höhe ab.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=60', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9719, 24, 12, 'ST', 'Neue Aufgaben an Kommunen nur übertragen, wenn sie vollständig finanziert sind', '{2404}', 9603, 2, 2, null, 'Verhindert neue ungedeckte Kosten bei den Kommunen und setzt an einer Ursache ihrer Finanznot an. Ein Ausgleich bestehender Aufgaben kostet das Land viel, die Wirkung ist kaum untersucht.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=61', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9720, 24, 12, 'ST', 'Dauerhaftes kommunales Infrastruktur- und Investitionsprogramm auflegen', '{2404}', 9601, 2, 2, null, 'Zusätzliche Investitionsmittel verringern den Investitionsrückstand der Kommunen. Programme sind aber oft zweckgebunden und an Personal für die Umsetzung gebunden.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=61', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9721, 24, 12, 'ST', 'Interkommunale Zusammenarbeit erleichtern und fördern', '{2404}', 9609, 1, 3, null, 'Gemeinsame Verwaltungseinheiten können Personal und Kosten bündeln. Große empirische Studien zu Einsparungen fehlen für Deutschland.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=49', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9722, 24, 12, 'ST', 'Genehmigungs- und Verwaltungsverfahren durchgängig digital, vom Antrag bis zum Bescheid', '{2404}', 9605, 1, 2, null, 'Digitale Verfahren können Personalmangel in Verwaltungen teilweise ausgleichen. Die Umsetzung dauert erfahrungsgemäß lange, und die Wirkung ist kaum gemessen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=56', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9723, 24, 12, 'ST', 'Leerstand im ländlichen Raum durch gezielte Abrissprogramme reduzieren', '{2402}', 9588, 1, 3, null, 'Rückbau und Hilfen bei Leerstand stabilisieren Wohnungsunternehmen und Ortsbilder. Das ist eine Reaktion auf die Schrumpfung, deren Ursache bleibt unberührt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=44', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9724, 24, 12, 'ST', 'Zusätzliche Personalmittel für Kitas, um das Kita-Netz besonders im ländlichen Raum zu sichern', '{2402}', 9576, 1, 3, null, 'Sichert vorhandene Betreuung bei sinkenden Kinderzahlen und hält Familien vor Ort. Neue Plätze entstehen nicht, deshalb ist kaum Wirkung auf die Geburten zu erwarten.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=27', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9725, 24, 12, 'ST', 'Entlastung von Eltern mit mehreren Kindern', '{2402}', 9579, 1, 2, null, 'Finanzielle Entlastung erleichtert das Leben mit Kindern. Studien finden aber meist nur schwache Effekte von Geldleistungen auf die Geburtenzahl, und die Kosten für den Landeshaushalt sind hoch.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=28', 'https://www.ifo.de/en/cesifo/publications/2024/working-paper/baby-bonus-fertility-and-missing-women', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9726, 24, 12, 'ST', 'Investitionen in Wohnheimplätze für Studierende und Auszubildende priorisieren', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=43', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9727, 24, 12, 'ST', 'Familien, die in ihrer Heimat bleiben wollen, mit zinslosen Krediten unterstützen', '{2401}', null, 1, 2, null, 'Zinslose Kredite können Familien das Bleiben erleichtern. Die Zusage ist unbestimmt, die Wirkung auf die Abwanderung ist kaum untersucht, und Arbeitsplätze bleiben entscheidend.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=44', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9728, 24, 12, 'ST', 'Ansiedlung von Landesbehörden in Mittelzentren und ländlichen Regionen', '{2401}', 9598, 1, 2, null, 'Mehr Arbeitsplätze und Angebote in kleineren Zentren können Abwanderung bremsen. Die Zusagen sind meist unbestimmt, und die Wirkung ist kaum belegt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=59', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9729, 24, 13, null, 'Wohnheime für Auszubildende und Studierende bauen, sanieren und über das Programm „Junges Wohnen“ fördern', '{2401}', 9619, 1, 3, null, 'Das Programm läuft bereits und senkt die Wohnkosten in Ausbildung und Studium. Ob das die Abwanderung aus ländlichen Regionen bremst, ist kaum untersucht.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=79', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9730, 24, 13, null, 'Hochschulstandorte mit Hörsälen, Laboren, Mensen und Bibliotheken modernisieren und als Lebensorte stärken', '{2401}', 9620, 1, 2, null, 'Bessere Hochschulen stärken Studienorte auch außerhalb der Metropolen. Die Wirkung auf die Abwanderung ist indirekt, und es braucht Vereinbarungen mit den Ländern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=80', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9731, 24, 13, null, 'Lebendige Ortskerne und Gemeindezentren unterstützen und fördern, damit Regionen auch für junge Familien attraktiv sind', '{2401}', 9622, 1, 2, null, 'Investitionen außerhalb der Metropolen können Regionen attraktiver machen. Die Zusagen sind unbestimmt, und die Wirkung auf die Abwanderung junger Menschen ist kaum belegt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=51', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9732, 24, 13, null, 'Führerscheinerwerb für Menschen in Ausbildung fördern', '{2401}', 9621, 1, 3, null, 'Mobilität erleichtert im ländlichen Raum den Weg zu Ausbildung und Arbeit ohne Umzug. Die Wirkung auf die Abwanderung ist nicht untersucht, es gibt Mitnahmeeffekte.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9733, 24, 13, null, 'Elterngeld: Mindest- und Höchstbetrag auf 500 bzw. 2.400 Euro erhöhen', '{2402}', 9616, 1, 2, null, 'Studien zum Elterngeld zeigen positive Geburteneffekte vor allem bei höheren Einkommen und Akademikerinnen, insgesamt aber kleine Effekte. Die Ausweitung kostet viel.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=82', 'https://ideas.repec.org/a/diw/diwvjh/83-1-9.html', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9734, 24, 13, null, 'Solidarische Ausbildungsumlage einführen, um die Ausbildungsbereitschaft kleiner und mittlerer Betriebe zu fördern', '{2403}', 9626, 2, 2, null, 'In der Pflege brachte die Umlage deutlich mehr Auszubildende. Für allgemeine Umlagen fehlen Belege, sie wirken nur bei echtem Stellenmangel, nicht bei Besetzungsproblemen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2026/heft/3/beitrag/zur-diskussion-einer-ausbildungsumlage-fuer-die-duale-berufsausbildung.html', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9735, 24, 13, null, 'Ausbildungsverbünde stärken, um die Zahl passender Ausbildungsstellen zu erhöhen', '{2403}', null, 1, 3, null, 'Verbünde ermöglichen kleinen Betrieben die Ausbildung und können mehr passende Stellen schaffen. Die Zusage ist ohne konkreten Umfang, die Wirkung ist kaum gemessen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9736, 24, 13, null, 'Ausbildungsgarantie inklusiv weiterentwickeln, damit alle jungen Menschen eine Ausbildung erhalten', '{2403}', 9627, 2, 2, null, 'Österreich gilt mit seiner Ausbildungsgarantie als Vorbild, wenn betriebliche Plätze fehlen. Wirkungsdaten sind begrenzt, und außerbetriebliche Plätze sind teuer.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', 'https://www.bertelsmann-stiftung.de/de/publikationen/publikation/did/die-ausbildungsgarantie-in-oesterreich-all', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9737, 24, 13, null, 'Instrument der Assistierten Ausbildung verbessern, damit alle jungen Menschen eine Ausbildung erhalten', '{2403}', 9627, 2, 2, null, 'Österreich gilt mit seiner Ausbildungsgarantie als Vorbild, wenn betriebliche Plätze fehlen. Wirkungsdaten sind begrenzt, und außerbetriebliche Plätze sind teuer.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=78', 'https://www.bertelsmann-stiftung.de/de/publikationen/publikation/did/die-ausbildungsgarantie-in-oesterreich-all', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9738, 24, 13, null, 'Berufsorientierung für junge Menschen verbessern und vor allem an Schulen informieren', '{2403}', 9624, 1, 2, null, 'Bessere Orientierung kann die Passung von Ausbildungswünschen und Stellen verbessern. Belastbare Wirkungsnachweise auf den Übergang in Ausbildung fehlen, Schulen sind Ländersache.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=79', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9739, 24, 13, null, 'Jugendberufsagenturen flächendeckend einrichten und stärken als zentrale Anlaufstelle', '{2403}', 9625, 2, 3, null, 'Eine zentrale Anlaufstelle setzt an der Vermittlung zwischen Bewerbern und Stellen an, Hamburg meldet mehr direkte Übergänge. Kausale Wirkungsstudien fehlen bisher.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=79', 'https://www.bibb.de/de/177236.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9740, 24, 13, null, 'Auskömmlichere Finanzierung der Kommunen und den Deutschlandfonds nutzen, damit Kommunen notwendige Investitionen finanzieren können', '{2404}', 9628, 2, 2, null, 'Zusätzliche Mittel setzen am Rekord-Investitionsrückstand der Kommunen an. Der Bund kann nur über Länder oder Sonderprogramme fördern, und die Mittel fließen wegen Personalmangel oft langsam ab.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=108', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9741, 24, 13, null, 'Förderprogramme für Kommunen zugunsten der Grundfinanzierung reduzieren und die verbleibenden vereinfachen', '{2404}', 9629, 2, 2, null, 'Kommunen nennen Antragsaufwand und Eigenanteile als Hürde, finanzschwache Kommunen gehen oft leer aus. Die Vereinfachung hilft gezielt, die Mittel bleiben aber begrenzt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=109', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9742, 24, 13, null, 'Beteiligung der Kommunen an Energieprojekten ausbauen', '{2404}', 9633, 1, 3, null, 'Verschafft Standortgemeinden zusätzliche Einnahmen. Das betrifft nur Kommunen mit Anlagen, die Beträge sind begrenzt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=109', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9743, 24, 13, 'BE', 'Azubiwerk mit günstigen Wohnheimen und Beratung für Auszubildende einrichten', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=197', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9744, 24, 13, 'BE', 'Hochschulverträge neu gestalten, Finanzierung der Hochschulen verlässlich erhöhen', '{2401}', 9590, 1, 2, null, 'Gut ausgestattete Hochschulen machen den Studienort attraktiver. Ohne Bezug zu ländlichen Standorten ist die Wirkung auf die Abwanderung junger Menschen aber indirekt, und die Kosten sind hoch.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=114', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9745, 24, 13, 'BE', 'Umbau des Flughafengebäudes Tegel zur Ansiedlung der Hochschule für Technik', '{2401}', 9590, 1, 2, null, 'Gut ausgestattete Hochschulen machen den Studienort attraktiver. Ohne Bezug zu ländlichen Standorten ist die Wirkung auf die Abwanderung junger Menschen aber indirekt, und die Kosten sind hoch.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=97', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9746, 24, 13, 'BE', 'Förderung des Kinderwunsches: Reproduktionsmedizin ausbauen, Kostenübernahme durch Krankenkassen', '{2402}', 9577, 2, 3, null, 'Nach den Kürzungen der Kassenleistungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Zuschüsse wirken also, aber nur für einen kleinen Teil der Geburten.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=206', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9747, 24, 13, 'BE', 'Unterstützung von Kommunen mit Wohnungsleerstand durch Wohnungsunternehmen in der Hauptstadtregion', '{2402}', 9588, 1, 3, null, 'Rückbau und Hilfen bei Leerstand stabilisieren Wohnungsunternehmen und Ortsbilder. Das ist eine Reaktion auf die Schrumpfung, deren Ursache bleibt unberührt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=63', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9748, 24, 13, 'BE', 'Konnexitätsgesetz für die Finanzierung der Bezirke etablieren („Wer bestellt, bezahlt“)', '{2404}', 9603, 2, 2, null, 'Verhindert neue ungedeckte Kosten bei den Kommunen und setzt an einer Ursache ihrer Finanznot an. Ein Ausgleich bestehender Aufgaben kostet das Land viel, die Wirkung ist kaum untersucht.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=245', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9749, 24, 13, 'BE', 'Typengenehmigungen und digitale Genehmigungsplattform für Bauanträge', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=61', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9750, 24, 13, 'BE', 'Strukturelle Nachteile der Bezirke bei Personalgewinnung und Personalbindung abbauen', '{2404}', 9607, 2, 2, null, 'Unterbesetzte Bauämter gelten laut Kommunalumfragen als zentrales Hemmnis für Investitionen. Mehr Personal setzt daran an, ist auf dem Arbeitsmarkt aber schwer zu gewinnen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=247', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9751, 24, 13, 'MV', 'Ausbau von Welcome Centern als Anlaufstellen für Fachkräfteeinwanderung und Berufsrückkehrer*innen', '{2401,2402}', 9584, 2, 2, null, 'Zuwanderung bremst die Alterung nachweislich, wenn auch ohne sie umzukehren. Schnellere Verfahren und Welcome Center erleichtern den Zuzug, das Aufenthaltsrecht regelt aber der Bund.', 'https://gruene-mv.de/?wpdmdl=33772#page=30', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9752, 24, 13, 'MV', 'Landesprogramm zur Förderung internationaler und englischsprachiger Studiengänge', '{2401}', 9592, 1, 3, null, 'Kann mehr Studierende ins Land holen. Ob sie nach dem Studium bleiben, hängt von Arbeitsplätzen ab, die Wirkung auf die Abwanderung ist kaum untersucht.', 'https://gruene-mv.de/?wpdmdl=33772#page=38', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9753, 24, 13, 'MV', 'Mehr bezahlbarer Wohnraum für Auszubildende', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://gruene-mv.de/?wpdmdl=33772#page=31', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9754, 24, 13, 'MV', 'Stärkere Vernetzung von Hochschulen und Fachschulen mit regionalen Unternehmen, damit Absolvent*innen im Land bleiben', '{2401}', 9593, 1, 3, null, 'Kontakte zu regionalen Betrieben schon im Studium fördern den Verbleib. Die Programme sind günstig, ihre Wirkung ist aber kaum evaluiert, und am Ende entscheiden passende Stellen.', 'https://gruene-mv.de/?wpdmdl=33772#page=30', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9755, 24, 13, 'MV', 'Stabsstelle in der Staatskanzlei für Jugendkultur gegen Abwanderung; Jugendkultur ausreichend finanzieren', '{2401}', null, 1, 3, null, 'Jugendkultur kann die Lebensqualität junger Menschen auf dem Land erhöhen. Für Wegzüge wegen Ausbildung und Beruf ist das aber nur ein Nebenfaktor, Belege fehlen.', 'https://gruene-mv.de/?wpdmdl=33772#page=64', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9756, 24, 13, 'MV', 'Investitionsprogramm für Hochschulbau und Infrastruktur', '{2401}', 9590, 1, 2, null, 'Gut ausgestattete Hochschulen machen den Studienort attraktiver. Ohne Bezug zu ländlichen Standorten ist die Wirkung auf die Abwanderung junger Menschen aber indirekt, und die Kosten sind hoch.', 'https://gruene-mv.de/?wpdmdl=33772#page=36', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9757, 24, 13, 'MV', 'Landesweite Modellzentren für Kinder und Familien langfristig sichern und flächendeckend ausbauen', '{2402}', 9582, 1, 3, null, 'Stärkt die Infrastruktur für Familien vor Ort. Eine Wirkung auf die Geburtenzahl oder den Zuzug ist kaum untersucht und allenfalls indirekt.', 'https://gruene-mv.de/?wpdmdl=33772#page=64', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9758, 24, 13, 'MV', 'Digitaler Bauantrag, flächendeckend und zügig eingeführt', '{2404}', 9605, 1, 2, null, 'Digitale Verfahren können Personalmangel in Verwaltungen teilweise ausgleichen. Die Umsetzung dauert erfahrungsgemäß lange, und die Wirkung ist kaum gemessen.', 'https://gruene-mv.de/?wpdmdl=33772#page=52', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9759, 24, 13, 'MV', 'Ausreichende Personalkapazitäten in den Bauämtern sicherstellen', '{2404}', 9607, 2, 2, null, 'Unterbesetzte Bauämter gelten laut Kommunalumfragen als zentrales Hemmnis für Investitionen. Mehr Personal setzt daran an, ist auf dem Arbeitsmarkt aber schwer zu gewinnen.', 'https://gruene-mv.de/?wpdmdl=33772#page=52', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9760, 24, 13, 'MV', 'Kommunen bei Wärmeplanung umfassend unterstützen, Beratung im Land verankern, Bundesförderung ergänzen', '{2404}', null, 1, 3, null, 'Beratung und Geld vom Land entlasten Kommunen bei einer neuen Pflichtaufgabe. Das betrifft nur die Wärmeplanung und nicht ihre allgemeine Finanz- und Personallage.', 'https://gruene-mv.de/?wpdmdl=33772#page=8', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9761, 24, 13, 'MV', 'Landesbodenfonds, mit dem das Land die Bodenpolitik der Kommunen unterstützt', '{2404}', null, 1, 2, null, 'Ein Bodenfonds gibt Kommunen mehr Spielraum beim Flächenerwerb. Er bindet Landesmittel und verbessert die allgemeine Finanzlage der Kommunen kaum.', 'https://gruene-mv.de/?wpdmdl=33772#page=53', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9762, 24, 13, 'ST', 'Berufsschulstandorte im ganzen Land erhalten; in jedem Landkreis bleibt mindestens eine Berufsschule', '{2401}', null, 2, 3, null, 'Eine Berufsschule in jedem Landkreis hält Ausbildungswege kurz, sodass Jugendliche für die Ausbildung nicht wegziehen müssen. Kleine Standorte sind teuer, und die Wirkung ist kaum untersucht.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=65', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9763, 24, 13, 'ST', 'Bau von Wohnheimen für Auszubildende, um Ausbildung in der Fläche attraktiver zu machen', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=65', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9764, 24, 13, 'ST', 'Werbekampagne in Berlin und Leipzig, die junge Familien für das Wohnen und Leben im ländlichen Raum anspricht', '{2402}', 9586, 1, 3, null, 'Werbung und gute Lebensbedingungen können Zuzug anstoßen. Ohne passende Arbeitsplätze ist die Wirkung von Kampagnen aber kaum belegt.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=92', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9765, 24, 13, 'ST', 'Öffnung der Förderung künstlicher Befruchtung durch das Land für queere Paare und ledige Frauen', '{2402}', 9577, 2, 3, null, 'Nach den Kürzungen der Kassenleistungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Zuschüsse wirken also, aber nur für einen kleinen Teil der Geburten.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=82', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9766, 24, 13, 'ST', 'Moderne Dorfzentren, die Angebote unter einem Dach bündeln, sollen die Grundversorgung vor Ort sichern', '{2402}', 9587, 1, 2, null, 'Dorfläden, zentrale Orte, Schulstandorte und Ehrenamt sichern die Versorgung schrumpfender Orte. Sie mildern Folgen der Alterung, ändern aber Geburten und Zuzug kaum.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=89', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9767, 24, 13, 'ST', 'Altschuldenfonds zur Entlastung strukturell überschuldeter Kommunen', '{2404}', 9602, 2, 2, null, 'Senkt Zins- und Tilgungslasten und schafft Spielraum, Erfahrungen gibt es etwa mit der Hessenkasse. Unabhängige Wirkungsstudien fehlen, und neue Schulden müssen verhindert werden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=97', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9768, 24, 13, 'ST', 'Daten und Digitalisierung bei öffentlichen Ausschreibungen (etwa BIM) verstärkt nutzen', '{2404}', 9605, 1, 2, null, 'Digitale Verfahren können Personalmangel in Verwaltungen teilweise ausgleichen. Die Umsetzung dauert erfahrungsgemäß lange, und die Wirkung ist kaum gemessen.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=92', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9769, 24, 13, 'ST', 'Bauordnung zu einer Umbauordnung weiterentwickeln und mit den Landesbauordnungen anderer Länder harmonisieren', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=92', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9770, 24, 14, null, 'Berufliche Bildungszentren besser nutzen und zu regionalen Innovations- und Gründerzentren ausbauen', '{2401}', null, 1, 2, null, 'Bildungszentren als regionale Innovations- und Gründerzentren können Perspektiven vor Ort schaffen. Die Wirkung auf den Verbleib junger Menschen ist kaum untersucht, die Zuständigkeit liegt zum Teil bei Ländern und Kammern.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9771, 24, 14, null, 'Angebote der Berufsorientierung stärken (u. a. Azubi-Botschafter, Jugendberufsagenturen)', '{2403}', 9624, 1, 2, null, 'Bessere Orientierung kann die Passung von Ausbildungswünschen und Stellen verbessern. Belastbare Wirkungsnachweise auf den Übergang in Ausbildung fehlen, Schulen sind Ländersache.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9772, 24, 14, null, 'Ausbildungskapazitäten der Länder erhöhen und Erzieherausbildung schulgeldfrei stellen', '{2403}', null, 1, 2, null, 'Eine schulgeldfreie Ausbildung und mehr Plätze erweitern das Ausbildungsangebot in einem Mangelberuf. Das betrifft nur einen Beruf, und die Schulen sind Ländersache.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=8', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9773, 24, 14, null, 'Nicht-kommerzielle Leihmutterschaft mit klarem Rechtsrahmen ermöglichen', '{2402}', null, 1, 2, null, 'Würde einzelnen Paaren mit Kinderwunsch helfen, insgesamt aber kaum mehr Geburten bringen. Dafür ist eine umstrittene Änderung des Embryonenschutzrechts nötig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9774, 24, 14, null, 'Bessere finanzielle Förderung von Kinderwunschbehandlungen', '{2402}', 9617, 2, 2, null, 'Nach den Kürzungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Bessere Finanzierung wirkt also, betrifft aber nur einen kleinen Teil der Geburten, und Kosten fallen an.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=31', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9775, 24, 14, null, 'Steuerliche Absetzbarkeit von Betreuungskosten und Unterhaltsleistungen für Familien verbessern', '{2402}', 9615, 1, 2, null, 'Entlastet Familien finanziell. Studien zum französischen Familiensplitting finden aber nur sehr schwache Effekte auf die Geburten, und die Kosten sind hoch.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=30', 'https://journals.openedition.org/economiepublique/279', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9776, 24, 14, null, 'Einwanderung in den Arbeitsmarkt für hochqualifizierte Fachkräfte erleichtern', '{2402}', 9618, 2, 3, null, 'Zuwanderung bremst die Alterung nachweislich, kehrt sie aber nicht um. Ob die Fachkräfte in strukturschwache Regionen ziehen und bleiben, ist offen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=27', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9777, 24, 14, null, 'Genehmigungsverfahren beschleunigen und Umweltgutachten abschaffen, Vorrang für Wohnungsbau', '{2404}', null, 1, 1, null, 'Weniger Gutachten beschleunigen Verfahren in Behörden. Umweltprüfungen sind weitgehend EU-rechtlich vorgegeben, an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9778, 24, 14, null, 'Rechtlichen Rahmen für durchgehend digitale Planung schaffen und Systeme in Behörden stärken', '{2404}', 9632, 1, 3, null, 'Schnellere Verfahren entlasten Behörden und Kommunen bei Bauprojekten. Wirkungsstudien zur Genehmigungsfiktion fehlen, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9779, 24, 14, 'BE', 'Mehr Ausbildungswohnheime schaffen, damit Auszubildende günstigen Wohnraum finden', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=13', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9780, 24, 14, 'BE', 'Ausländische Absolventinnen und Absolventen erhalten eineinhalb Jahre Zeit für die Arbeitsplatzsuche, mit Beratung', '{2401}', 9593, 1, 3, null, 'Kontakte zu regionalen Betrieben schon im Studium fördern den Verbleib. Die Programme sind günstig, ihre Wirkung ist aber kaum evaluiert, und am Ende entscheiden passende Stellen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=98', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9781, 24, 14, 'BE', 'Englisch als Verkehrssprache in der Hochschulverwaltung anbieten, um internationale Studierende nach Berlin zu holen', '{2402}', null, 1, 3, null, 'Englisch in der Hochschulverwaltung erleichtert internationalen Studierenden und Forschenden den Zuzug. Der Effekt auf die Bevölkerungsentwicklung ist gering, und ob sie bleiben, ist offen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=14', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9782, 24, 14, 'BE', 'Die zusätzliche Finanzierung von Kinderwunschbehandlungen durch das Land soll niemanden schlechterstellen; Bund soll Kassenfinanzierung öffnen', '{2402}', 9577, 2, 3, null, 'Nach den Kürzungen der Kassenleistungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Zuschüsse wirken also, aber nur für einen kleinen Teil der Geburten.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=82', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9783, 24, 14, 'BE', 'Mehr Kitaplätze und Tagespflege mit flexibleren Öffnungszeiten schaffen', '{2402}', 9575, 2, 2, null, 'Studien aus Deutschland zeigen, dass mehr Krippenplätze die Geburtenrate leicht erhöhen, vor allem bei zweiten und dritten Kindern. Der Effekt ist begrenzt, und es fehlen Fachkräfte.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=113', 'https://ifo.de/publikationen/2013/working-paper/does-expanding-public-child-care-encourage-fertility-county-level', 'belegt', '2026-10-11', false, true, 'blind'),
  (9784, 24, 14, 'BE', 'Einwanderungsverfahren für Fachkräfte vereinfachen und beschleunigen, Umzug mit Arbeitsvertrag in maximal sechs Wochen', '{2402}', 9584, 2, 2, null, 'Zuwanderung bremst die Alterung nachweislich, wenn auch ohne sie umzukehren. Schnellere Verfahren und Welcome Center erleichtern den Zuzug, das Aufenthaltsrecht regelt aber der Bund.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=98', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9785, 24, 14, 'BE', 'Personal und Mittel der Planungsämter auf Gebiete mit vielen Wohnungsneubauten konzentrieren', '{2404}', 9607, 2, 2, null, 'Unterbesetzte Bauämter gelten laut Kommunalumfragen als zentrales Hemmnis für Investitionen. Mehr Personal setzt daran an, ist auf dem Arbeitsmarkt aber schwer zu gewinnen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=46', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9786, 24, 14, 'BE', 'Genehmigungen mit kurzen Entscheidungsfristen und Genehmigungsfiktion bei Untätigkeit der Verwaltung', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=21', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9787, 24, 14, 'BE', 'KI-basierte Verwaltungssoftware gegen Personalmangel in der Berliner Verwaltung einführen', '{2404}', 9605, 1, 2, null, 'Digitale Verfahren können Personalmangel in Verwaltungen teilweise ausgleichen. Die Umsetzung dauert erfahrungsgemäß lange, und die Wirkung ist kaum gemessen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=45', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9788, 24, 14, 'BE', 'Grund- und Gewerbesteuer langfristig abschaffen und durch kommunalen Zuschlag mit Hebesatzrecht ersetzen', '{2404}', 9612, 1, 1, null, 'Ein Umbau kann die Einnahmen der Kommunen verbreitern oder stabilisieren. Die Gesetzgebung liegt beim Bund, und das Aufkommen hängt von der Ausgestaltung ab.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=50', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9789, 24, 14, 'BE', 'Regionalverband Berlin-Brandenburg per Staatsvertrag mit eigenem Haushalt und Zuständigkeiten errichten', '{2404}', 9609, 1, 3, null, 'Gemeinsame Verwaltungseinheiten können Personal und Kosten bündeln. Große empirische Studien zu Einsparungen fehlen für Deutschland.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=23', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9790, 24, 14, 'MV', 'Examensstudiengang Rechtswissenschaften an der Universität Rostock wieder eröffnen, um junge Talente vom Abwandern abzuhalten', '{2401}', 9591, 2, 2, null, 'Viele Absolventen, besonders von Fachhochschulen, bleiben in der Region ihres Studiums oder kehren zurück. Entscheidend sind aber passende Jobs vor Ort, und neue Standorte brauchen Jahre.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=139', 'https://www.bmluk.gv.at/themen/landwirtschaft/bildung-forschung/Online-Fachzeitschrift-Laendlicher-Raum/archiv/2013/Hochqualifizierte.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9791, 24, 14, 'MV', 'Altersgrenze für die Klasse AM (Motorrollerführerschein) auf 14 Jahre senken, um die Mobilität junger Menschen zu erhöhen', '{2401}', null, 1, 1, null, 'Früher mobil zu sein kann Jugendlichen auf dem Land Wege zu Schule und Ausbildung erleichtern. Das Mindestalter regelt der Bund in der Fahrerlaubnis-Verordnung, und es gibt Sicherheitsbedenken.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=61', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9792, 24, 14, 'MV', 'Auf Bundesebene ein Einwanderungsgesetz mit Punktesystem für Fachkräfte einfordern', '{2402}', null, 1, 1, null, 'Ein Punktesystem kann die Fachkräfteeinwanderung steuern. Das Land kann es nur auf Bundesebene einfordern, und ob dadurch mehr Fachkräfte in strukturschwache Regionen ziehen, ist offen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=16', null, 'gemischt', '2026-10-11', false, true, 'blind'),
  (9793, 24, 14, 'MV', 'Landesprogramm für Familien, deren Kinderwunsch wegen gesundheitlicher Einschränkungen unerfüllt bleibt', '{2402}', 9577, 2, 3, null, 'Nach den Kürzungen der Kassenleistungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Zuschüsse wirken also, aber nur für einen kleinen Teil der Geburten.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=38', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9794, 24, 14, 'MV', 'Gezielte Programme zur Stärkung ehrenamtlicher Strukturen im ländlichen Raum, wo Bevölkerungsrückgang Vereine gefährdet', '{2402}', 9587, 1, 2, null, 'Dorfläden, zentrale Orte, Schulstandorte und Ehrenamt sichern die Versorgung schrumpfender Orte. Sie mildern Folgen der Alterung, ändern aber Geburten und Zuzug kaum.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=122', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9795, 24, 14, 'MV', 'Familien durch Familienfreibeträge stärker steuerlich entlasten', '{2402}', 9580, 1, 1, null, 'Steuerliche Anreize erhöhen die Geburtenrate laut französischen Daten nur sehr schwach. Das Land kann diese Leistungen nicht selbst einführen, sondern nur über den Bundesrat werben.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=72', 'https://journals.openedition.org/economiepublique/279', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9796, 24, 14, 'MV', 'Mehr Mitarbeiter- und Azubiwohnungen durch weniger Bürokratie, schnellere Genehmigungen und flexiblere Baurechtsregeln', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=16', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9797, 24, 14, 'MV', 'Berufsbildungszentren finanziell und infrastrukturell stärken und zu regionalen Innovationszentren ausbauen', '{2401}', 9596, 1, 3, null, 'Gute Ausstattung macht die Ausbildung im Land attraktiver. Ohne Zusage für Standorte in der Fläche hilft das gegen die Abwanderung junger Menschen nur am Rand.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=7', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9798, 24, 14, 'MV', 'Freiwillige interkommunale Zusammenarbeit fördern, etwa durch gemeinsame Verwaltungseinheiten', '{2404}', 9609, 1, 3, null, 'Gemeinsame Verwaltungseinheiten können Personal und Kosten bündeln. Große empirische Studien zu Einsparungen fehlen für Deutschland.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=79', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9799, 24, 14, 'MV', 'Keine zusätzlichen Aufgaben an die Kommunen übertragen; bestehende Aufgaben kritisch hinterfragen', '{2404}', 9603, 2, 2, null, 'Verhindert neue ungedeckte Kosten bei den Kommunen und setzt an einer Ursache ihrer Finanznot an. Ein Ausgleich bestehender Aufgaben kostet das Land viel, die Wirkung ist kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=76', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9800, 24, 14, 'MV', 'Kommunen über den Finanzausgleich entlasten: Investitionsmittel ohne kleinteilige Förderprogramme ausreichen', '{2404}', 9600, 2, 3, null, 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=66', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9801, 24, 14, 'MV', 'Genehmigungsfiktionen einführen: Ist die Verwaltung nicht fristgerecht entschieden, gilt die Genehmigung als erteilt', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=57', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9802, 24, 14, 'MV', 'Landesangebote mit Künstlicher Intelligenz schaffen, die Abläufe in Kommunen straffen und Insellösungen vermeiden', '{2404}', 9605, 1, 2, null, 'Digitale Verfahren können Personalmangel in Verwaltungen teilweise ausgleichen. Die Umsetzung dauert erfahrungsgemäß lange, und die Wirkung ist kaum gemessen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=79', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9803, 24, 14, 'MV', 'Präventive Kommunalaufsicht, die schon vor finanziellen Notlagen beratend unterstützt', '{2404}', null, 1, 3, null, 'Eine beratende Kommunalaufsicht kann finanzielle Notlagen früher erkennen. Mehr Geld bringt sie den Kommunen nicht, und die Wirkung ist kaum untersucht.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=79', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9804, 24, 14, 'ST', 'Bestehende Hochschulstandorte, vor allem im ländlichen Raum, gezielt unterstützen und strukturell fördern', '{2401}', 9591, 2, 2, null, 'Viele Absolventen, besonders von Fachhochschulen, bleiben in der Region ihres Studiums oder kehren zurück. Entscheidend sind aber passende Jobs vor Ort, und neue Standorte brauchen Jahre.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=33', 'https://www.bmluk.gv.at/themen/landwirtschaft/bildung-forschung/Online-Fachzeitschrift-Laendlicher-Raum/archiv/2013/Hochqualifizierte.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9805, 24, 14, 'ST', 'Angemessene Versorgung mit studentischem Wohnraum sichern', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=33', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9806, 24, 14, 'ST', 'Ab Klasse 7 regelmäßige Unternehmensbesuche und Praktika für Schülerinnen und Schüler etablieren', '{2401}', 9597, 1, 3, null, 'Frühe Kontakte zu Betrieben vor Ort können junge Menschen an die Region binden. Belastbare Belege zur Wirkung auf den Verbleib fehlen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=31', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9807, 24, 14, 'ST', 'Modellprojekt für Gemeinschaftsbüros mit Kinderbetreuung und Betreuungszusammenschlüsse, auch im ländlichen Raum', '{2402}', null, 1, 3, null, 'Ein Modellprojekt kann Beruf und Kinderbetreuung besser vereinbar machen. Es ist klein angelegt, und eine Wirkung auf die Geburten ist offen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=24', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9808, 24, 14, 'ST', 'Zugang zum Arbeitsmarkt für Zuwanderer erleichtern; Aufenthaltstitel für Beschäftigung innerhalb von vier Wochen', '{2402}', 9584, 2, 2, null, 'Zuwanderung bremst die Alterung nachweislich, wenn auch ohne sie umzukehren. Schnellere Verfahren und Welcome Center erleichtern den Zuzug, das Aufenthaltsrecht regelt aber der Bund.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=10', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9809, 24, 14, 'ST', 'Zentrale Orte als Anker für Versorgung, Bildung, Arbeit und Gesundheit stärken und an ihr Umland anbinden', '{2402}', 9587, 1, 2, null, 'Dorfläden, zentrale Orte, Schulstandorte und Ehrenamt sichern die Versorgung schrumpfender Orte. Sie mildern Folgen der Alterung, ändern aber Geburten und Zuzug kaum.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=58', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9810, 24, 14, 'ST', 'Sachsen-Anhalt als Lebens- und Arbeitsraum für Zuzug attraktiv machen (Wohnen, Internet, Coworking)', '{2402}', 9586, 1, 3, null, 'Werbung und gute Lebensbedingungen können Zuzug anstoßen. Ohne passende Arbeitsplätze ist die Wirkung von Kampagnen aber kaum belegt.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=58', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9811, 24, 14, 'ST', 'Landesengagementstrategie neu ausrichten und auf den demographischen Wandel lenken', '{2402}', 9587, 1, 2, null, 'Dorfläden, zentrale Orte, Schulstandorte und Ehrenamt sichern die Versorgung schrumpfender Orte. Sie mildern Folgen der Alterung, ändern aber Geburten und Zuzug kaum.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=51', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9812, 24, 14, 'ST', 'Landeseigenen, befristeten Altschuldenfonds auflegen, der kommunale Wohnungsunternehmen und Genossenschaften gleichbehandelt', '{2404}', null, 1, 2, null, 'Ein Altschuldenfonds entlastet kommunale Wohnungsunternehmen und damit indirekt die Kommunen. Die Haushalte der Kommunen selbst werden kaum entlastet, und der Fonds bindet Landesmittel.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=12', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9813, 24, 14, 'ST', 'Jahresabschlüsse von Kommunen entschlacken; Aufstellungsfrist von vier auf sechs Monate verlängern', '{2404}', 9606, 1, 3, null, 'Weniger Vorgaben entlasten die Verwaltungen der Kommunen. Die Zusagen sind meist unbestimmt, und an der Finanzlage ändern sie wenig.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=49', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9814, 24, 14, 'ST', 'Fördermittel für Kommunen möglichst in pauschalierte investive Zuweisungen überführen', '{2404}', 9600, 2, 3, null, 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=50', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9815, 24, 14, 'ST', 'Einnahmebasis der Kommunen stärken: stärkere Beteiligung an Einkommen- und Umsatzsteuer, Gewerbesteuer sichern', '{2404}', 9611, 2, 1, null, 'Eine höhere Steuerbeteiligung würde die Finanzbasis der Kommunen dauerhaft stärken. Das Land kann das aber nur über Bundesrat und Bund erreichen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=50', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9816, 24, 14, 'ST', 'Einwohnerzahlen für Finanzzuweisungen stärker an den Melderegistern ausrichten', '{2404}', null, 1, 3, null, 'Genauere Einwohnerzahlen können Zuweisungen gerechter verteilen. Insgesamt kommt dadurch kein zusätzliches Geld zu den Kommunen.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=50', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9817, 24, 14, 'ST', 'Echte Konnexität: Kosten übertragener kommunaler Aufgaben vollständig ausgleichen (Spitzabrechnung)', '{2404}', 9603, 2, 2, null, 'Verhindert neue ungedeckte Kosten bei den Kommunen und setzt an einer Ursache ihrer Finanznot an. Ein Ausgleich bestehender Aufgaben kostet das Land viel, die Wirkung ist kaum untersucht.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=50', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9818, 24, 14, 'ST', 'Für zentrale Genehmigungen verbindliche Entscheidungsfristen und online verfolgbare Verfahren einführen', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=43', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9819, 24, 14, 'ST', 'Gemeinsame Einrichtung des Landes und der Kommunen für kommunale Dienstleistungen schaffen', '{2404}', 9609, 1, 3, null, 'Gemeinsame Verwaltungseinheiten können Personal und Kosten bündeln. Große empirische Studien zu Einsparungen fehlen für Deutschland.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=51', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9820, 24, 15, null, 'Rückgewinnungsprogramme für abgewanderte Leistungsträger auflegen.', '{2401}', null, 1, 3, null, 'Rückkehrprogramme können abgewanderte Fachkräfte ansprechen. Rückkehr hängt aber vor allem von Familie und Arbeitsmarkt ab, und die Wirkung solcher Programme ist kaum untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=114', 'https://www.l-iz.de/politik/kassensturz/2013/12/Abwanderer-kehren-haeufiger-nach-Ostdeutschland-zurueck-52723', 'offen', '2026-10-11', false, true, 'blind'),
  (9821, 24, 15, null, 'Berufsorientierung an Schulen früher praktizieren, um mehr ausbildungsfähige Schulabgänger zu gewinnen.', '{2403}', 9624, 1, 2, null, 'Bessere Orientierung kann die Passung von Ausbildungswünschen und Stellen verbessern. Belastbare Wirkungsnachweise auf den Übergang in Ausbildung fehlen, Schulen sind Ländersache.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9822, 24, 15, null, 'Einmalige Willkommensprämie von 20.000 € bei der Geburt eines Kindes, bei fehlenden Rentenbeiträgen als Gutschrift.', '{2402}', null, 2, 1, null, 'Studien zu hohen Geburtsprämien finden kleine positive Effekte. Bei rund 20.000 Euro je Kind entstehen Kosten von über zehn Milliarden Euro im Jahr, deren Finanzierung ungeklärt ist.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', 'https://www.ifo.de/en/cesifo/publications/2024/working-paper/baby-bonus-fertility-and-missing-women', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9823, 24, 15, null, 'Ehegattensplitting auf ein Familiensplitting ausweiten, um Familien mit Kindern steuerlich zu entlasten.', '{2402}', 9615, 1, 2, null, 'Entlastet Familien finanziell. Studien zum französischen Familiensplitting finden aber nur sehr schwache Effekte auf die Geburten, und die Kosten sind hoch.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=60', 'https://journals.openedition.org/economiepublique/279', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9824, 24, 15, null, 'Ausreichend Kita-Plätze bereitstellen, mit Vorrang für Familien mit berufstätigen Eltern und Alleinerziehenden.', '{2402}', 9614, 2, 2, null, 'Mehr Krippenplätze erhöhen laut Studien die Geburtenrate leicht. Zuständig sind die Länder, der Bund kann über Investitionsprogramme beitragen, und es fehlt Personal.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=21', 'https://ifo.de/publikationen/2013/working-paper/does-expanding-public-child-care-encourage-fertility-county-level', 'belegt', '2026-10-11', false, true, 'blind'),
  (9825, 24, 15, null, 'Punktesystem mit Auswahlkriterien für außereuropäische Fachkräfte einführen, Branchen und Quoten festlegen.', '{2402}', 9618, 2, 3, null, 'Zuwanderung bremst die Alterung nachweislich, kehrt sie aber nicht um. Ob die Fachkräfte in strukturschwache Regionen ziehen und bleiben, ist offen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=114', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9826, 24, 15, null, 'Konnexitätsprinzip strikt einhalten, damit Kommunen nicht für Aufgaben anderer Ebenen zahlen.', '{2404}', 9631, 1, 1, null, 'Würde neue ungedeckte Lasten verhindern. Der Bund darf Kommunen keine Aufgaben direkt übertragen, eine Ausgleichspflicht würde eine Verfassungsänderung erfordern, und die Zusage ist unbestimmt.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=56', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9827, 24, 15, null, 'Grundsteuer abschaffen; Kommunen werden über einen Zuschlag auf Einkommen- und Körperschaftsteuer entschädigt.', '{2404}', null, 1, 1, null, 'Ein Zuschlag auf die Einkommensteuer könnte die Grundsteuer ersetzen, ohne dass die Kommunen mehr Geld bekommen. Nötig wäre eine Grundgesetzänderung, und die Einnahmen würden stärker schwanken.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=59', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9828, 24, 15, null, 'Planungs- und Genehmigungsverfahren für Infrastrukturprojekte vereinfachen, um Neuinvestitionen zu beschleunigen.', '{2404}', 9632, 1, 3, null, 'Schnellere Verfahren entlasten Behörden und Kommunen bei Bauprojekten. Wirkungsstudien zur Genehmigungsfiktion fehlen, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9829, 24, 15, null, 'Digitalisierung der Verwaltung vorantreiben.', '{2404}', 9632, 1, 3, null, 'Schnellere Verfahren entlasten Behörden und Kommunen bei Bauprojekten. Wirkungsstudien zur Genehmigungsfiktion fehlen, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=15', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9830, 24, 15, 'BE', 'Rückkehrprogramm für junge Wissenschaftler, die im Ausland arbeiten', '{2401}', 9595, 1, 3, null, 'Rückkehr kommt vor, vor allem aus familiären Gründen, und Rückkehrende ziehen oft aufs Land. Die Wirkung gezielter Programme und Prämien ist kaum untersucht.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=37', 'https://www.l-iz.de/politik/kassensturz/2013/12/Abwanderer-kehren-haeufiger-nach-Ostdeutschland-zurueck-52723', 'offen', '2026-10-11', false, true, 'blind'),
  (9831, 24, 15, 'BE', 'Mehr entfristete Stellen für Nachwuchs in der Wissenschaft, finanziert über die Hochschulverträge', '{2401}', null, 1, 2, null, 'Dauerstellen machen eine Wissenschaftskarriere im Land planbarer und halten Nachwuchs. Das betrifft wenige Personen und kostet die Hochschulen dauerhaft Geld.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=37', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9832, 24, 15, 'BE', 'Ausbau des Studienplatzangebots für Ärzte und Apotheker in Berlin', '{2401}', 9591, 2, 2, null, 'Viele Absolventen, besonders von Fachhochschulen, bleiben in der Region ihres Studiums oder kehren zurück. Entscheidend sind aber passende Jobs vor Ort, und neue Standorte brauchen Jahre.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=70', 'https://www.bmluk.gv.at/themen/landwirtschaft/bildung-forschung/Online-Fachzeitschrift-Laendlicher-Raum/archiv/2013/Hochqualifizierte.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9833, 24, 15, 'BE', 'Wohnheime für Auszubildende schaffen', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=32', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9834, 24, 15, 'BE', 'Steuerliches Familiensplitting zusätzlich zum Kindergeld', '{2402}', 9580, 1, 1, null, 'Steuerliche Anreize erhöhen die Geburtenrate laut französischen Daten nur sehr schwach. Das Land kann diese Leistungen nicht selbst einführen, sondern nur über den Bundesrat werben.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=58', 'https://journals.openedition.org/economiepublique/279', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9835, 24, 15, 'BE', 'Landeserziehungsgeld für Familien mit U3-Kindern, das den Kosten eines Kita-Platzes entspricht', '{2402}', 9579, 1, 2, null, 'Finanzielle Entlastung erleichtert das Leben mit Kindern. Studien finden aber meist nur schwache Effekte von Geldleistungen auf die Geburtenzahl, und die Kosten für den Landeshaushalt sind hoch.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=59', 'https://www.ifo.de/en/cesifo/publications/2024/working-paper/baby-bonus-fertility-and-missing-women', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9836, 24, 15, 'BE', 'Kita-Platzangebot erhalten und bedarfsgerecht ausbauen', '{2402}', 9575, 2, 2, null, 'Studien aus Deutschland zeigen, dass mehr Krippenplätze die Geburtenrate leicht erhöhen, vor allem bei zweiten und dritten Kindern. Der Effekt ist begrenzt, und es fehlen Fachkräfte.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=60', 'https://ifo.de/publikationen/2013/working-paper/does-expanding-public-child-care-encourage-fertility-county-level', 'belegt', '2026-10-11', false, true, 'blind'),
  (9837, 24, 15, 'BE', 'Familiengründung als verbindliches Thema in den Schullehrplänen', '{2402}', 9583, 1, 3, null, 'Kampagnen und Unterrichtsinhalte sind leicht umzusetzen. Eine Wirkung auf Kinderwunsch und Geburten ist nicht belegt, materielle Hürden bleiben bestehen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=61', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9838, 24, 15, 'BE', 'Einwanderung nur in staatlich definierte Bedarfsbereiche und mit Voraussetzungen', '{2402}', null, 0, 1, null, 'Zusätzliche Voraussetzungen würden die Zuwanderung eher verringern als erleichtern. Das Aufenthaltsrecht ist Bundessache, das Land kann es nicht selbst regeln.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=21', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9839, 24, 15, 'BE', 'Regelungen der Berliner Bauordnung entschlacken, Baugenehmigungen beschleunigen', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=9', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9840, 24, 15, 'BE', 'Stärkung der Bezirke durch eigene Einnahmequellen', '{2404}', null, 1, 1, null, 'Eigene Einnahmen würden die Selbstständigkeit der Bezirke stärken. Dafür sind Verfassungs- und Steuerrechtsänderungen nötig, und der Umfang ist unklar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=76', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9841, 24, 15, 'MV', 'Rückgewinnungsprogramme für gut ausgebildete Leistungsträger, die das Land verlassen haben', '{2401}', 9595, 1, 3, null, 'Rückkehr kommt vor, vor allem aus familiären Gründen, und Rückkehrende ziehen oft aufs Land. Die Wirkung gezielter Programme und Prämien ist kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=14', 'https://www.l-iz.de/politik/kassensturz/2013/12/Abwanderer-kehren-haeufiger-nach-Ostdeutschland-zurueck-52723', 'offen', '2026-10-11', false, true, 'blind'),
  (9842, 24, 15, 'MV', 'Studiengang Rechtswissenschaft mit Staatsexamen an der Universität Rostock wieder einführen', '{2401}', 9591, 2, 2, null, 'Viele Absolventen, besonders von Fachhochschulen, bleiben in der Region ihres Studiums oder kehren zurück. Entscheidend sind aber passende Jobs vor Ort, und neue Standorte brauchen Jahre.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=35', 'https://www.bmluk.gv.at/themen/landwirtschaft/bildung-forschung/Online-Fachzeitschrift-Laendlicher-Raum/archiv/2013/Hochqualifizierte.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9843, 24, 15, 'MV', 'Schwellenwerte für freihändige und vereinfachte Auftragsvergabe deutlich erhöhen', '{2404}', 9610, 1, 3, null, 'Höhere Wertgrenzen verkürzen Vergabeverfahren in den Kommunen. Dagegen sprechen weniger Wettbewerb und mögliche höhere Preise, die Wirkung ist kaum untersucht.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=13', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9844, 24, 15, 'MV', 'Finanzmittel für Kommunen vorrangig über den allgemeinen kommunalen Finanzausgleich bereitstellen', '{2404}', 9600, 2, 3, null, 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=57', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9845, 24, 15, 'MV', 'Unterstützungsnetzwerk für Schwangere in Not ausbauen, mit Hilfen in und nach der Schwangerschaft', '{2402}', 9581, 1, 3, null, 'Unterstützung kann Schwangeren in schwierigen Lagen helfen. Ob dadurch insgesamt mehr Kinder geboren werden, ist kaum untersucht und wohl nur ein kleiner Effekt.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=21', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9846, 24, 15, 'MV', 'Baby-Begrüßungsgeld von 3.000 Euro, in drei Raten ausgezahlt', '{2402}', 9578, 1, 3, null, 'Studien aus Korea und Australien finden kleine positive Effekte von Geburtsprämien. Bei 2.000 bis 4.000 Euro ist aber kaum eine Änderung der Familienplanung zu erwarten, und es gibt Mitnahmeeffekte.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=19', 'https://www.ifo.de/en/cesifo/publications/2024/working-paper/baby-bonus-fertility-and-missing-women', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9847, 24, 15, 'MV', 'Familiensplitting auf Bundesebene: Familieneinkommen zusammenzählen und auf alle Familienmitglieder aufteilen', '{2402}', 9580, 1, 1, null, 'Steuerliche Anreize erhöhen die Geburtenrate laut französischen Daten nur sehr schwach. Das Land kann diese Leistungen nicht selbst einführen, sondern nur über den Bundesrat werben.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=22', 'https://journals.openedition.org/economiepublique/279', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9848, 24, 15, 'ST', 'Rückkehrprogramm für ausgewanderte deutsche Fachkräfte mit Hilfe bei Wohnungs- und Kitasuche und einer Rückkehrprämie.', '{2401}', 9595, 1, 3, null, 'Rückkehr kommt vor, vor allem aus familiären Gründen, und Rückkehrende ziehen oft aufs Land. Die Wirkung gezielter Programme und Prämien ist kaum untersucht.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=42', 'https://www.l-iz.de/politik/kassensturz/2013/12/Abwanderer-kehren-haeufiger-nach-Ostdeutschland-zurueck-52723', 'offen', '2026-10-11', false, true, 'blind'),
  (9849, 24, 15, 'ST', 'Führerschein-Zuschuss für Auszubildende, gekoppelt an den Abschluss; soll Mobilität junger Menschen im ländlichen Raum sichern.', '{2401}', null, 1, 3, null, 'Ein Führerscheinzuschuss erleichtert Auszubildenden im ländlichen Raum die Mobilität ohne Umzug. Da er erst nach dem Abschluss gezahlt wird, hilft er beim Start wenig, und es gibt Mitnahmeeffekte.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=147', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9850, 24, 15, 'ST', 'Pädagogische Hochschule gründen, an der die Lehrerausbildung gebündelt wird (neuer Studienstandort).', '{2401}', 9591, 2, 2, null, 'Viele Absolventen, besonders von Fachhochschulen, bleiben in der Region ihres Studiums oder kehren zurück. Entscheidend sind aber passende Jobs vor Ort, und neue Standorte brauchen Jahre.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=84', 'https://www.bmluk.gv.at/themen/landwirtschaft/bildung-forschung/Online-Fachzeitschrift-Laendlicher-Raum/archiv/2013/Hochqualifizierte.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9851, 24, 15, 'ST', 'Baby-Begrüßungsgeld für Eltern je Kind, gestaffelt nach Kinderzahl und in zwei Teilen ausgezahlt.', '{2402}', 9578, 1, 3, null, 'Studien aus Korea und Australien finden kleine positive Effekte von Geburtsprämien. Bei 2.000 bis 4.000 Euro ist aber kaum eine Änderung der Familienplanung zu erwarten, und es gibt Mitnahmeeffekte.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=11', 'https://www.ifo.de/en/cesifo/publications/2024/working-paper/baby-bonus-fertility-and-missing-women', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9852, 24, 15, 'ST', 'Kinder und Familie stärker in Werbe- und Aufklärungskampagnen der Landesregierung herausstellen.', '{2402}', 9583, 1, 3, null, 'Kampagnen und Unterrichtsinhalte sind leicht umzusetzen. Eine Wirkung auf Kinderwunsch und Geburten ist nicht belegt, materielle Hürden bleiben bestehen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=13', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9853, 24, 15, 'ST', 'Breit aufgestellte Unterstützungsstruktur für ungewollt Schwangere aufbauen.', '{2402}', 9581, 1, 3, null, 'Unterstützung kann Schwangeren in schwierigen Lagen helfen. Ob dadurch insgesamt mehr Kinder geboren werden, ist kaum untersucht und wohl nur ein kleiner Effekt.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=12', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9854, 24, 15, 'ST', 'Krippen und Kindergärten ab dem ersten Kind kostenlos machen.', '{2402}', null, 1, 2, null, 'Entlastet Familien finanziell. Die Gebührenfreiheit führte in Studien nur zu kurzfristigen Effekten und hohen Mitnahmeeffekten, eine Wirkung auf Geburten ist nicht belegt, und die Kosten sind hoch.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=18', 'https://www.diw.de/de/diw_01.c.698972.de/publikationen/wochenberichte/2019_48/gebuehrenbefreiung_des_letzten_kita___jahres__muetter_weiten_ihre_arbeitszeit_nur_kurzfristig_aus.html', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9855, 24, 15, 'ST', 'Verteilung von Migranten in den ländlichen Raum verhindern; keine Asylzentren und Zuweisungsquoten in den Gemeinden.', '{2402}', null, 0, 2, null, 'Würde den Zuzug in ländliche Gemeinden verringern statt ihn zu stärken. Das Land kann die Verteilung zwar regeln, muss dann aber andere Kommunen stärker belasten.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=191', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9856, 24, 15, 'ST', 'Sonderprogramme für Nahversorgung, Dorfläden und Seniorenangebote im ländlichen Raum.', '{2402}', 9587, 1, 2, null, 'Dorfläden, zentrale Orte, Schulstandorte und Ehrenamt sichern die Versorgung schrumpfender Orte. Sie mildern Folgen der Alterung, ändern aber Geburten und Zuzug kaum.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=192', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9857, 24, 15, 'ST', 'Finanzausgleichsgesetz grundlegend reformieren: höhere Finanzausgleichsmasse, Konnexitätsausgleich.', '{2404}', 9599, 2, 2, null, 'Mehr und verlässlichere Zuweisungen setzen direkt an der knappen Finanzlage an, die laut Umfragen Investitionen bremst. Das belastet aber den Landeshaushalt und hängt von der Höhe ab.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=232', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9858, 24, 15, 'ST', 'Genehmigungsfiktion: Anträge gelten als genehmigt, wenn eine Behörde die Entscheidungsfrist überschreitet.', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=214', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9859, 24, 15, 'ST', 'Kommunen mehr Entscheidungsspielraum geben.', '{2404}', 9606, 1, 3, null, 'Weniger Vorgaben entlasten die Verwaltungen der Kommunen. Die Zusagen sind meist unbestimmt, und an der Finanzlage ändern sie wenig.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=189', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9860, 24, 16, null, 'Strukturpolitik und Infrastrukturinvestitionen, damit Regionen außerhalb der Metropolen attraktiver werden und ländliche Regionen nicht veröden', '{2401}', 9622, 1, 2, null, 'Investitionen außerhalb der Metropolen können Regionen attraktiver machen. Die Zusagen sind unbestimmt, und die Wirkung auf die Abwanderung junger Menschen ist kaum belegt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9861, 24, 16, null, 'Künstliche Befruchtung für alle, von den gesetzlichen Krankenkassen (teil-)finanziert', '{2402}', 9617, 2, 2, null, 'Nach den Kürzungen 2004 halbierten sich die Behandlungen, und es kamen weniger Kinder zur Welt. Bessere Finanzierung wirkt also, betrifft aber nur einen kleinen Teil der Geburten, und Kosten fallen an.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=47', 'https://www.aerztezeitung.de/Politik/Schmidt-widerspricht-Bundesrats-Votum-355714.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9862, 24, 16, null, 'Fossile Kraftwerksstandorte sollen als Fachkräfte- und Ausbildungsstandorte erhalten bleiben', '{2401}', null, 1, 2, null, 'Bestehende Ausbildungsstandorte in Strukturwandelregionen zu erhalten, hält Ausbildungsangebote vor Ort. Die Zusage ist unbestimmt und hängt von Unternehmensentscheidungen ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=34', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9863, 24, 16, null, 'Solidarische Ausbildungsumlage: Betriebe, die nicht ausbilden, zahlen in einen Fonds, der Ausbildungsplätze finanziert', '{2403}', 9626, 2, 2, null, 'In der Pflege brachte die Umlage deutlich mehr Auszubildende. Für allgemeine Umlagen fehlen Belege, sie wirken nur bei echtem Stellenmangel, nicht bei Besetzungsproblemen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', 'https://www.wirtschaftsdienst.eu/inhalt/jahr/2026/heft/3/beitrag/zur-diskussion-einer-ausbildungsumlage-fuer-die-duale-berufsausbildung.html', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9864, 24, 16, null, 'Duale Ausbildung stärken und flächenweit anbieten', '{2403}', null, 1, 3, null, 'Ein flächendeckendes Angebot an dualer Ausbildung kann Matching-Probleme mindern. Die Zusage ist unbestimmt und nennt kein Instrument.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=38', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9865, 24, 16, null, 'Berufsvorbereitende Maßnahmen sollen mit einem verbindlichen Ausbildungsangebot enden', '{2403}', 9627, 2, 2, null, 'Österreich gilt mit seiner Ausbildungsgarantie als Vorbild, wenn betriebliche Plätze fehlen. Wirkungsdaten sind begrenzt, und außerbetriebliche Plätze sind teuer.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=40', 'https://www.bertelsmann-stiftung.de/de/publikationen/publikation/did/die-ausbildungsgarantie-in-oesterreich-all', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9866, 24, 16, null, 'Unternehmen beteiligen sich im ländlichen Raum an bezahlbaren Wohnheimplätzen für Auszubildende', '{2401}', null, 1, 1, null, 'Eine Pflichtbeteiligung von Unternehmen könnte mehr Azubi-Wohnplätze auf dem Land finanzieren. Ob eine solche Abgabe rechtlich zulässig ist, ist ungeklärt, und Belege zur Wirkung fehlen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=39', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9867, 24, 16, null, 'Kommunale Altschulden und Überschuldung durch Entschuldungspaket des Bundes beseitigen', '{2404}', 9630, 2, 1, null, 'Eine Entschuldung würde hoch verschuldeten Kommunen Spielraum verschaffen. Dafür braucht es voraussichtlich eine Grundgesetzänderung und eine Einigung mit den Ländern, die Wirkung ist kaum evaluiert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=44', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9868, 24, 16, null, 'Gemeindefinanzreform mit voller Anrechnung der kommunalen Finanzkraft im Länderfinanzausgleich', '{2404}', null, 1, 2, null, 'Würde finanzschwache Länder und damit indirekt deren Kommunen stärken. Dafür ist eine schwierige Einigung von Bund und Ländern über den Finanzausgleich nötig, und es kommt nicht direkt bei den Kommunen an.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=13', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9869, 24, 16, null, 'Gewerbesteuer reformieren und zur Gemeindewirtschaftsteuer umbauen', '{2404}', null, 1, 2, null, 'Eine breitere Gemeindewirtschaftsteuer könnte die Einnahmen der Kommunen stabilisieren und erhöhen. Der Umbau ist politisch umstritten, und das Aufkommen hängt von der Ausgestaltung ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=12', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9870, 24, 16, null, 'Soforthilfeprogramm: Kommunen in Finanzkrisen erhalten Mittel aus einem Bundesfonds für soziale Infrastruktur', '{2404}', 9628, 2, 2, null, 'Zusätzliche Mittel setzen am Rekord-Investitionsrückstand der Kommunen an. Der Bund kann nur über Länder oder Sonderprogramme fördern, und die Mittel fließen wegen Personalmangel oft langsam ab.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=44', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9871, 24, 16, null, 'Bund übernimmt in vollem Umfang die Sozialleistungen, die die kommunalen Haushalte belasten', '{2404}', null, 2, 1, null, 'Würde die Kommunen massiv entlasten, da Sozialausgaben ein Haupttreiber ihrer Defizite sind. Das kostet den Bund zweistellige Milliardenbeträge und erfordert eine Neuordnung der Finanzverfassung.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=44', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9872, 24, 16, null, 'Förderprogramme auch ohne kommunale Eigenmittel zugänglich machen und bürokratische Hürden abbauen', '{2404}', 9629, 2, 2, null, 'Kommunen nennen Antragsaufwand und Eigenanteile als Hürde, finanzschwache Kommunen gehen oft leer aus. Die Vereinfachung hilft gezielt, die Mittel bleiben aber begrenzt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=44', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9873, 24, 16, null, 'Kommunen erhalten einen Bonus je Megawatt neuer Windkraft- und PV-Großanlagen', '{2404}', 9633, 1, 3, null, 'Verschafft Standortgemeinden zusätzliche Einnahmen. Das betrifft nur Kommunen mit Anlagen, die Beträge sind begrenzt.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=33', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9874, 24, 16, 'BE', 'Programm für Studierenden- und Azubiwohnheime mit erweiterten Krediten und öffentlichen Zuschüssen', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=29', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9875, 24, 16, 'BE', 'Berliner Azubi-Werk gründen, das bezahlbaren Wohnraum für Auszubildende bereitstellt', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=106', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9876, 24, 16, 'BE', 'Mieten für Studierendenwohnheimplätze begrenzen', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=178', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9877, 24, 16, 'BE', 'Hochschulverträge abschließen, die Hochschulen auskömmlich finanzieren', '{2401}', 9590, 1, 2, null, 'Gut ausgestattete Hochschulen machen den Studienort attraktiver. Ohne Bezug zu ländlichen Standorten ist die Wirkung auf die Abwanderung junger Menschen aber indirekt, und die Kosten sind hoch.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=219', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9878, 24, 16, 'BE', 'Berliner Familienfördergesetz umsetzen und weiterentwickeln (Familienzentren sichern)', '{2402}', 9582, 1, 3, null, 'Stärkt die Infrastruktur für Familien vor Ort. Eine Wirkung auf die Geburtenzahl oder den Zuzug ist kaum untersucht und allenfalls indirekt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=183', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9879, 24, 16, 'BE', 'Bezirke erhalten einen größeren Anteil am Sondervermögen des Bundes', '{2404}', 9599, 2, 2, null, 'Mehr und verlässlichere Zuweisungen setzen direkt an der knappen Finanzlage an, die laut Umfragen Investitionen bremst. Das belastet aber den Landeshaushalt und hängt von der Höhe ab.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=77', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9880, 24, 16, 'BE', 'Baustellen-Genehmigungen durch Digitalisierung und Ausstattung der Behörden beschleunigen', '{2404}', 9605, 1, 2, null, 'Digitale Verfahren können Personalmangel in Verwaltungen teilweise ausgleichen. Die Umsetzung dauert erfahrungsgemäß lange, und die Wirkung ist kaum gemessen.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=69', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9881, 24, 16, 'MV', 'Career-Center an Hochschulen etablieren, um Studierende nach dem Studium mit Karriereberatung in der Region zu halten.', '{2401}', 9593, 1, 3, null, 'Kontakte zu regionalen Betrieben schon im Studium fördern den Verbleib. Die Programme sind günstig, ihre Wirkung ist aber kaum evaluiert, und am Ende entscheiden passende Stellen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=17', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9882, 24, 16, 'MV', 'Mehr Wohnheimplätze für Studierende und Auszubildende schaffen.', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=6', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9883, 24, 16, 'MV', 'Strukturschwache Regionen gezielt und dauerhaft fördern (Zuordnung zur Abwanderung offen).', '{2401}', 9598, 1, 2, null, 'Mehr Arbeitsplätze und Angebote in kleineren Zentren können Abwanderung bremsen. Die Zusagen sind meist unbestimmt, und die Wirkung ist kaum belegt.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=26', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9884, 24, 16, 'MV', 'Bezahlte Elternzeit (28 Tage) für den zweiten Elternteil nach der Geburt einführen.', '{2402}', 9580, 1, 1, null, 'Steuerliche Anreize erhöhen die Geburtenrate laut französischen Daten nur sehr schwach. Das Land kann diese Leistungen nicht selbst einführen, sondern nur über den Bundesrat werben.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=15', 'https://journals.openedition.org/economiepublique/279', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9885, 24, 16, 'MV', 'Mindeststandards für soziale Infrastruktur in allen Regionen erarbeiten und verlässlich finanzieren (Zuordnung offen).', '{2402}', 9587, 1, 2, null, 'Dorfläden, zentrale Orte, Schulstandorte und Ehrenamt sichern die Versorgung schrumpfender Orte. Sie mildern Folgen der Alterung, ändern aber Geburten und Zuzug kaum.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=11', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9886, 24, 16, 'MV', 'Regionale seniorenpolitische Gesamtkonzepte etablieren und umsetzen (Zuordnung offen).', '{2402}', 9587, 1, 2, null, 'Dorfläden, zentrale Orte, Schulstandorte und Ehrenamt sichern die Versorgung schrumpfender Orte. Sie mildern Folgen der Alterung, ändern aber Geburten und Zuzug kaum.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=12', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9887, 24, 16, 'MV', 'Pauschale Zuweisungen an Kommunen erhöhen, z. B. Infrastrukturpauschale und Regionalbudgets.', '{2404}', 9600, 2, 3, null, 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=25', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9888, 24, 16, 'MV', 'Kommunen bei Projektbürokratie entlasten.', '{2404}', 9606, 1, 3, null, 'Weniger Vorgaben entlasten die Verwaltungen der Kommunen. Die Zusagen sind meist unbestimmt, und an der Finanzlage ändern sie wenig.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=8', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9889, 24, 16, 'ST', 'Umverteilung zugunsten der Städte und Gemeinden über den Finanzausgleich', '{2404}', 9599, 2, 2, null, 'Mehr und verlässlichere Zuweisungen setzen direkt an der knappen Finanzlage an, die laut Umfragen Investitionen bremst. Das belastet aber den Landeshaushalt und hängt von der Höhe ab.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=79', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9890, 24, 16, 'ST', 'Gemeindewirtschaftssteuer mit einheitlichem Freibetrag, um die Finanzkraft der Kommunen zu stärken', '{2404}', 9612, 1, 1, null, 'Ein Umbau kann die Einnahmen der Kommunen verbreitern oder stabilisieren. Die Gesetzgebung liegt beim Bund, und das Aufkommen hängt von der Ausgestaltung ab.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=18', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9891, 24, 16, 'ST', 'Schuldenschnitt für kommunale Altschulden auf Bundesebene', '{2404}', 9613, 2, 1, null, 'Ein Schuldenschnitt würde den Kommunen große Spielräume verschaffen. Das Land kann ihn nicht allein umsetzen, die Finanzierung durch den Bund ist offen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=79', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9892, 24, 16, 'ST', 'Kommunale Pauschalförderung statt vieler Anträge, ohne endlose Anträge und Formulare', '{2404}', 9600, 2, 3, null, 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=79', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9893, 24, 16, 'ST', 'Kofinanzierungsanteil der Kommunen bei Stadtumbauprogrammen senken und Förderung einfacher nutzbar machen', '{2404}', 9600, 2, 3, null, 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=83', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9894, 24, 16, 'ST', 'Mehr Personal und bessere Ausstattung für Kommunen durch das Land', '{2404}', 9607, 2, 2, null, 'Unterbesetzte Bauämter gelten laut Kommunalumfragen als zentrales Hemmnis für Investitionen. Mehr Personal setzt daran an, ist auf dem Arbeitsmarkt aber schwer zu gewinnen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=77', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9895, 24, 16, 'ST', 'Begleitung von Studierenden vom ersten Semester bis zum Berufseinstieg in Sachsen-Anhalt', '{2401}', 9593, 1, 3, null, 'Kontakte zu regionalen Betrieben schon im Studium fördern den Verbleib. Die Programme sind günstig, ihre Wirkung ist aber kaum evaluiert, und am Ende entscheiden passende Stellen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=38', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9896, 24, 16, 'ST', 'Mehr Landesmittel für Wohnheimplätze für Auszubildende und Studierende', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=85', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9897, 24, 16, 'ST', 'Ausbau des Hochschulstandorts Anhalt und Merseburg, Forschung zu Recycling', '{2401}', 9591, 2, 2, null, 'Viele Absolventen, besonders von Fachhochschulen, bleiben in der Region ihres Studiums oder kehren zurück. Entscheidend sind aber passende Jobs vor Ort, und neue Standorte brauchen Jahre.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=123', 'https://www.bmluk.gv.at/themen/landwirtschaft/bildung-forschung/Online-Fachzeitschrift-Laendlicher-Raum/archiv/2013/Hochqualifizierte.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9898, 24, 16, 'ST', 'Willkommenszentren als Netzwerk für Kommunen, Initiativen und Behörden', '{2402}', 9584, 2, 2, null, 'Zuwanderung bremst die Alterung nachweislich, wenn auch ohne sie umzukehren. Schnellere Verfahren und Welcome Center erleichtern den Zuzug, das Aufenthaltsrecht regelt aber der Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=98', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9899, 24, 16, 'ST', 'Integrationsbudget, mit dem Kommunen unbürokratisch Mittel für Integration erhalten', '{2402}', 9585, 1, 2, null, 'Sprachkurse und Integrationsmittel können dazu beitragen, dass Zugewanderte bleiben. Die Wirkung auf die Bevölkerungsentwicklung ist indirekt, Integrationskurse finanziert zum Teil der Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=97', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9900, 24, 16, 'ST', 'Kindergrundsicherung, damit Familienplanung nicht vom Geldbeutel abhängt', '{2402}', 9580, 1, 1, null, 'Steuerliche Anreize erhöhen die Geburtenrate laut französischen Daten nur sehr schwach. Das Land kann diese Leistungen nicht selbst einführen, sondern nur über den Bundesrat werben.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=45', 'https://journals.openedition.org/economiepublique/279', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9901, 24, 16, 'ST', 'Sprachkurse für alle Zugewanderten, auch im ländlichen Raum', '{2402}', 9585, 1, 2, null, 'Sprachkurse und Integrationsmittel können dazu beitragen, dass Zugewanderte bleiben. Die Wirkung auf die Bevölkerungsentwicklung ist indirekt, Integrationskurse finanziert zum Teil der Bund.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=98', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9902, 24, 17, null, 'Recht auf einen Ausbildungsplatz für jeden jungen Menschen garantieren', '{2403}', 9627, 2, 2, null, 'Österreich gilt mit seiner Ausbildungsgarantie als Vorbild, wenn betriebliche Plätze fehlen. Wirkungsdaten sind begrenzt, und außerbetriebliche Plätze sind teuer.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', 'https://www.bertelsmann-stiftung.de/de/publikationen/publikation/did/die-ausbildungsgarantie-in-oesterreich-all', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9903, 24, 17, null, 'Bundesweites Praktikumskonzept für Kooperation von Betrieben und Schulen bei der Berufsorientierung', '{2403}', 9624, 1, 2, null, 'Bessere Orientierung kann die Passung von Ausbildungswünschen und Stellen verbessern. Belastbare Wirkungsnachweise auf den Übergang in Ausbildung fehlen, Schulen sind Ländersache.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9904, 24, 17, null, 'Berufsbildungspakt, um Berufsschulen zu modernisieren und besser auszustatten', '{2403}', null, 1, 2, null, 'Modernere Berufsschulen machen die duale Ausbildung attraktiver und können die Besetzung von Stellen erleichtern. Berufsschulen sind Ländersache, der Bund kann nur über einen Pakt mitfinanzieren.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9905, 24, 17, null, 'Bund beteiligt sich an der Grundfinanzierung und dem Hochschulbau, um die Unterfinanzierung der Hochschulen zu beenden', '{2401}', 9620, 1, 2, null, 'Bessere Hochschulen stärken Studienorte auch außerhalb der Metropolen. Die Wirkung auf die Abwanderung ist indirekt, und es braucht Vereinbarungen mit den Ländern.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=25', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9906, 24, 17, null, 'Kita-Beiträge stabil halten oder senken und mittelfristig beitragsfrei machen', '{2402}', null, 1, 2, null, 'Niedrigere Beiträge entlasten Familien. Laut Studien gibt es bei Gebührenfreiheit hohe Mitnahmeeffekte und kaum dauerhafte Wirkungen, Kitas sind zudem Ländersache.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=24', 'https://www.diw.de/de/diw_01.c.698972.de/publikationen/wochenberichte/2019_48/gebuehrenbefreiung_des_letzten_kita___jahres__muetter_weiten_ihre_arbeitszeit_nur_kurzfristig_aus.html', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9907, 24, 17, null, 'Unternehmen stärker in die Pflicht nehmen, Kita-Plätze bereitzustellen, mit steuerlichen Vorteilen als Ausgleich', '{2402}', 9614, 2, 2, null, 'Mehr Krippenplätze erhöhen laut Studien die Geburtenrate leicht. Zuständig sind die Länder, der Bund kann über Investitionsprogramme beitragen, und es fehlt Personal.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', 'https://ifo.de/publikationen/2013/working-paper/does-expanding-public-child-care-encourage-fertility-county-level', 'belegt', '2026-10-11', false, true, 'blind'),
  (9908, 24, 17, null, 'Investitionsprogramm für kinder-, jugend- und familienfreundliche Infrastruktur', '{2402}', 9614, 2, 2, null, 'Mehr Krippenplätze erhöhen laut Studien die Geburtenrate leicht. Zuständig sind die Länder, der Bund kann über Investitionsprogramme beitragen, und es fehlt Personal.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=32', 'https://ifo.de/publikationen/2013/working-paper/does-expanding-public-child-care-encourage-fertility-county-level', 'belegt', '2026-10-11', false, true, 'blind'),
  (9909, 24, 17, null, 'Kostenfreie, verlässliche Ferienbetreuung für Kinder anbieten', '{2402}', null, 1, 2, null, 'Verlässliche Ferienbetreuung erleichtert berufstätigen Eltern den Alltag. Eine Wirkung auf die Geburten ist nicht untersucht, Betreuung ist Ländersache, und die Finanzierung ist offen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=33', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9910, 24, 17, null, 'Kommunen die nötigen finanziellen Mittel bereitstellen, damit sie ihre Ausgaben selbst priorisieren können', '{2404}', 9628, 2, 2, null, 'Zusätzliche Mittel setzen am Rekord-Investitionsrückstand der Kommunen an. Der Bund kann nur über Länder oder Sonderprogramme fördern, und die Mittel fließen wegen Personalmangel oft langsam ab.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=16', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9911, 24, 17, null, 'Vereinfachtes Genehmigungsverfahren für sozialen Wohnungsbau und vereinfachtes serielles Bauen', '{2404}', 9632, 1, 3, null, 'Schnellere Verfahren entlasten Behörden und Kommunen bei Bauprojekten. Wirkungsstudien zur Genehmigungsfiktion fehlen, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9912, 24, 17, 'BE', 'Landeszuschüsse für die Hochschulen auf mindestens zwei Prozent des Bruttoinlandsprodukts erhöhen', '{2401}', null, 1, 1, null, 'Deutlich mehr Geld macht die Hochschulen attraktiver. Zwei Prozent des BIP wären ein Vielfaches des heutigen Haushalts und sind nicht finanziert, die Wirkung auf die Abwanderung ist indirekt.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=17', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9913, 24, 17, 'BE', 'Studentenwohnheim-Fonds für den Neubau bezahlbarer Wohnheimplätze innerhalb von fünf Jahren', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=17', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9914, 24, 17, 'BE', 'Aufnahme qualifizierter Fachkräfte vereinfachen und attraktiver gestalten', '{2402}', 9584, 2, 2, null, 'Zuwanderung bremst die Alterung nachweislich, wenn auch ohne sie umzukehren. Schnellere Verfahren und Welcome Center erleichtern den Zuzug, das Aufenthaltsrecht regelt aber der Bund.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=36', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9915, 24, 17, 'BE', 'Jedem neugeborenen Kind eine Erstausstattung („Babybox“) ermöglichen', '{2402}', null, 1, 3, null, 'Eine Babybox ist eine sichtbare Willkommensgeste für Familien. Wegen des geringen Werts ist eine Wirkung auf die Geburten nicht zu erwarten.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=23', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9916, 24, 17, 'BE', 'Mutterschutz für Selbständige einführen', '{2402}', 9580, 1, 1, null, 'Steuerliche Anreize erhöhen die Geburtenrate laut französischen Daten nur sehr schwach. Das Land kann diese Leistungen nicht selbst einführen, sondern nur über den Bundesrat werben.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=42', 'https://journals.openedition.org/economiepublique/279', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9917, 24, 17, 'BE', 'Finanzreform zur Entlastung der Kommunen; Länder und Gemeinden bei finanzwirksamen Bundesgesetzen stärken', '{2404}', 9611, 2, 1, null, 'Eine höhere Steuerbeteiligung würde die Finanzbasis der Kommunen dauerhaft stärken. Das Land kann das aber nur über Bundesrat und Bund erreichen.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=53', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9918, 24, 17, 'BE', 'Genehmigungsfiktion stärker nutzen: beantragte Genehmigungen gelten nach Fristablauf als erteilt', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=42', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9919, 24, 17, 'BE', 'Vergaberecht reformieren, damit kleine Unternehmen leichter an öffentliche Aufträge kommen (Direktvergabe bis 50.000 €)', '{2404}', 9610, 1, 3, null, 'Höhere Wertgrenzen verkürzen Vergabeverfahren in den Kommunen. Dagegen sprechen weniger Wettbewerb und mögliche höhere Preise, die Wirkung ist kaum untersucht.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=42', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9920, 24, 17, 'BE', 'Planungs- und Bauprozesse straffen', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=50', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9921, 24, 17, 'BE', 'Personal für die Verwaltung gewinnen: Ausbildungsbetriebe ansprechen, duale Studiengänge ausbauen, Quereinstieg', '{2404}', 9608, 1, 2, null, 'Kann den Personalmangel in der Verwaltung lindern. Ein Bezug zu kommunalen Bau- und Planungsaufgaben ist nur teilweise gegeben, die Wirkung ist kaum belegt.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=63', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9922, 24, 17, 'BE', 'Stellenbesetzungsverfahren im öffentlichen Dienst durch Abbau von Regularien verkürzen', '{2404}', 9608, 1, 2, null, 'Kann den Personalmangel in der Verwaltung lindern. Ein Bezug zu kommunalen Bau- und Planungsaufgaben ist nur teilweise gegeben, die Wirkung ist kaum belegt.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=62', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9923, 24, 17, 'MV', 'Gezielte Förderung von Familien, besonders Alleinerziehender und Familien mit niedrigem oder mittlerem Einkommen', '{2402}', 9579, 1, 2, null, 'Finanzielle Entlastung erleichtert das Leben mit Kindern. Studien finden aber meist nur schwache Effekte von Geldleistungen auf die Geburtenzahl, und die Kosten für den Landeshaushalt sind hoch.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=12', 'https://www.ifo.de/en/cesifo/publications/2024/working-paper/baby-bonus-fertility-and-missing-women', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9924, 24, 17, 'MV', 'Abwanderung von Know-how und Fachkräften stoppen, indem Perspektiven für Umsetzung und Wachstum im Land geschaffen werden', '{2401}', 9598, 1, 2, null, 'Mehr Arbeitsplätze und Angebote in kleineren Zentren können Abwanderung bremsen. Die Zusagen sind meist unbestimmt, und die Wirkung ist kaum belegt.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=34', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9925, 24, 17, 'MV', 'Verbindliche Praktika in Betrieben als fester Bestandteil schulischer Bildung, um junge Menschen für die Region zu gewinnen', '{2401}', 9597, 1, 3, null, 'Frühe Kontakte zu Betrieben vor Ort können junge Menschen an die Region binden. Belastbare Belege zur Wirkung auf den Verbleib fehlen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=32', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9926, 24, 17, 'MV', 'Förderung von studentischem Wohnraum, besonders in Hochschulstädten', '{2401}', 9589, 1, 3, null, 'Bezahlbares Wohnen erleichtert Ausbildung und Studium im Land, Befragungen zeigen hohe Wohnkostenlasten. Ob Plätze in Hochschulstädten die Abwanderung aus ländlichen Regionen senken, ist offen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=52', 'https://www.berlin.de/hjav/themen/azubiwerk/azubiwerk-berlin-ein-wichtiger-schritt-fuer-bessere-ausbildungsbedingungen-1635959.php', 'offen', '2026-10-11', false, true, 'blind'),
  (9927, 24, 17, 'MV', 'Beschleunigte und vereinfachte Anerkennung ausländischer Berufs- und Bildungsabschlüsse', '{2402}', 9584, 2, 2, null, 'Zuwanderung bremst die Alterung nachweislich, wenn auch ohne sie umzukehren. Schnellere Verfahren und Welcome Center erleichtern den Zuzug, das Aufenthaltsrecht regelt aber der Bund.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=31', 'https://www.bpb.de/themen/soziale-lage/demografischer-wandel/576716/internationale-migration-als-chance-fuer-den-demografischen-wandel/', 'gemischt', '2026-10-11', false, true, 'blind'),
  (9928, 24, 17, 'MV', 'Pauschale Zuweisungen an Kommunen statt kleinteiliger Förderprogramme, insbesondere aus Bundesmitteln', '{2404}', 9600, 2, 3, null, 'Kommunen nennen aufwendige Anträge und Personalmangel als Investitionshemmnis. Pauschalen entlasten die Verwaltung und machen Geld planbar, sind ohne zusätzliche Mittel aber nur eine Umschichtung.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=76', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9929, 24, 17, 'MV', 'Gemeinden sollen ohne zusätzlichen Antrag verbindlich an den Erträgen der Windenergie beteiligt werden, zweckfrei', '{2404}', null, 1, 3, null, 'Eine verpflichtende Beteiligung bringt Standortgemeinden ohne Antragsaufwand zusätzliche Einnahmen. Sie betrifft nur Gemeinden mit Windanlagen, und die Beträge sind begrenzt.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=25', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9930, 24, 17, 'MV', 'Vereinheitlichung von Formularen und Verfahren für Kommunen, Bürger, Unternehmen und Verwaltung', '{2404}', 9606, 1, 3, null, 'Weniger Vorgaben entlasten die Verwaltungen der Kommunen. Die Zusagen sind meist unbestimmt, und an der Finanzlage ändern sie wenig.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=76', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9931, 24, 17, 'MV', 'Entscheidungsspielräume der Kommunen stärken, unnötige bürokratische Anforderungen absenken', '{2404}', 9606, 1, 3, null, 'Weniger Vorgaben entlasten die Verwaltungen der Kommunen. Die Zusagen sind meist unbestimmt, und an der Finanzlage ändern sie wenig.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=29', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9932, 24, 17, 'MV', 'Beschleunigung von Planungs- und Genehmigungsverfahren', '{2404}', 9604, 1, 3, null, 'Kürzere Verfahren entlasten Bauämter und beschleunigen Projekte. Zur Genehmigungsfiktion fehlen Wirkungsstudien, Fachverbände befürchten Risiken, und an der Finanzlage der Kommunen ändert sich wenig.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=29', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9933, 24, 17, 'MV', 'Verteilung von Geflüchteten nach der Leistungsfähigkeit der Kommunen', '{2404}', null, 1, 3, null, 'Eine Verteilung nach Leistungsfähigkeit entlastet stark beanspruchte Kommunen. An ihrer grundsätzlichen Finanzlage ändert sie wenig.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=74', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9934, 24, 17, 'ST', 'Mittelzentren als Wohn-, Arbeits- und Versorgungsstandorte stärken: Förderung des Wohnungsbaus, Ansiedlung von Unternehmen und bessere ÖPNV-Anbindung an die Oberzentren', '{2401}', 9598, 1, 2, null, 'Mehr Arbeitsplätze und Angebote in kleineren Zentren können Abwanderung bremsen. Die Zusagen sind meist unbestimmt, und die Wirkung ist kaum belegt.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=29', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9935, 24, 17, 'ST', 'Allen Absolventen eines Lehramtsstudiums in Sachsen-Anhalt ein Stellenangebot im Schuldienst machen', '{2401}', null, 2, 2, null, 'Eine sichere Stelle im Land nach dem Lehramtsstudium bindet Absolventen direkt, auch für ländliche Schulen. Sie setzt freie Planstellen und Geld voraus und gilt nur für einen Beruf.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9936, 24, 17, 'ST', 'Mehr Studienplätze für das Lehramt schaffen und den Praxisbezug ausbauen', '{2401}', 9591, 2, 2, null, 'Viele Absolventen, besonders von Fachhochschulen, bleiben in der Region ihres Studiums oder kehren zurück. Entscheidend sind aber passende Jobs vor Ort, und neue Standorte brauchen Jahre.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=52', 'https://www.bmluk.gv.at/themen/landwirtschaft/bildung-forschung/Online-Fachzeitschrift-Laendlicher-Raum/archiv/2013/Hochqualifizierte.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9937, 24, 17, 'ST', 'Hochschulabsolventen sollen nach dem Abschluss ein bis zwei Jahre Uni-Werkstätten und -Infrastruktur nutzen können, wenn sie ihr Gewerbe in Sachsen-Anhalt anmelden', '{2401}', 9593, 1, 3, null, 'Kontakte zu regionalen Betrieben schon im Studium fördern den Verbleib. Die Programme sind günstig, ihre Wirkung ist aber kaum evaluiert, und am Ende entscheiden passende Stellen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=89', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9938, 24, 17, 'ST', 'Bei Schrumpfung den Erhalt kleiner Grundschulstandorte im ländlichen Raum sichern', '{2402}', 9587, 1, 2, null, 'Dorfläden, zentrale Orte, Schulstandorte und Ehrenamt sichern die Versorgung schrumpfender Orte. Sie mildern Folgen der Alterung, ändern aber Geburten und Zuzug kaum.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=76', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9939, 24, 17, 'ST', 'Reform der Finanzbeziehungen zwischen Bund, Land und Kommunen und höherer kommunaler Anteil an den Steuereinnahmen', '{2404}', 9611, 2, 1, null, 'Eine höhere Steuerbeteiligung würde die Finanzbasis der Kommunen dauerhaft stärken. Das Land kann das aber nur über Bundesrat und Bund erreichen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=76', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9940, 24, 17, 'ST', 'Landesinvestitionsprogramme auflegen und den Kommunalfinanzausgleich stärken', '{2404}', 9599, 2, 2, null, 'Mehr und verlässlichere Zuweisungen setzen direkt an der knappen Finanzlage an, die laut Umfragen Investitionen bremst. Das belastet aber den Landeshaushalt und hängt von der Höhe ab.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=19', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9941, 24, 17, 'ST', 'Vollständige Entschuldung der Kommunen durch Bund und Land', '{2404}', 9613, 2, 1, null, 'Ein Schuldenschnitt würde den Kommunen große Spielräume verschaffen. Das Land kann ihn nicht allein umsetzen, die Finanzierung durch den Bund ist offen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=19', null, 'offen', '2026-10-11', false, true, 'blind'),
  (9942, 24, 17, 'ST', 'Planungs- und Umsetzungskapazitäten in Verwaltung und Kommunen dauerhaft ausbauen', '{2404}', 9607, 2, 2, null, 'Unterbesetzte Bauämter gelten laut Kommunalumfragen als zentrales Hemmnis für Investitionen. Mehr Personal setzt daran an, ist auf dem Arbeitsmarkt aber schwer zu gewinnen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=19', 'https://www.kfw.de/%C3%9Cber-die-KfW/Newsroom/Aktuelles/Pressemitteilungen-Details_855680.html', 'belegt', '2026-10-11', false, true, 'blind'),
  (9943, 24, 17, 'ST', 'Landeseinheitliche Softwarelösungen, Bürokratieabbau und serviceorientierte Landesverwaltung gegenüber den Kommunen', '{2404}', 9605, 1, 2, null, 'Digitale Verfahren können Personalmangel in Verwaltungen teilweise ausgleichen. Die Umsetzung dauert erfahrungsgemäß lange, und die Wirkung ist kaum gemessen.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=76', null, 'offen', '2026-10-11', false, true, 'blind');

